\usepackage[textsize=tiny]{todonotes}

\title{Optimal Time Complexities of \\Parallel Stochastic Optimization Methods \\ Under a Fixed Computation Model}

\author{%
  Alexander Tyurin\\
  KAUST\\
  Saudi Arabia\\
  \texttt{alexandertiurin@gmail.com} \\
  \And
  Peter Richt\'{a}rik \\
  KAUST\\
  Saudi Arabia\\
  \texttt{richtarik@gmail.com} \\
}

\begin{document}

\maketitle

\begin{abstract}
    Parallelization is a popular strategy for improving the performance of iterative algorithms. Optimization methods are no exception: design of efficient parallel optimization methods and tight analysis of their theoretical properties are important research endeavors. While the minimax complexities are well known for sequential optimization methods, the theory of parallel optimization methods is less explored. In this paper, we propose a new protocol that generalizes the classical oracle framework approach. Using this protocol, we establish {\em minimax complexities for parallel optimization methods} that have access to an unbiased stochastic gradient oracle with bounded variance. We consider a fixed computation model characterized by each worker requiring a fixed but worker-dependent time to calculate stochastic gradient. We prove lower bounds and develop optimal algorithms that attain them. Our results have surprising consequences for the literature of {\em asynchronous} optimization methods.
\end{abstract}

\section{Introduction}
\label{sec:introduction}
We consider the  nonconvex optimization problem
\begin{align}
    \label{eq:main_task}
    \squeeze \min \limits_{x \in Q} \Big \{f(x) \eqdef \ExpSub{\xi \sim \mathcal{D}}{f(x;\xi)}\Big \},
\end{align}
where $f\,:\,\R^d \times \mathbb{S}_{\xi} \rightarrow \R,$ $Q \subseteq \R^d,$ and $\xi$ is a random variable with some distribution $\mathcal{D}$ on $\mathbb{S}_{\xi}.$ In machine learning, $\mathbb{S}_\xi$ could be the space of all possible data, $\mathcal{D}$ is the distribution of the training dataset, and $f(\cdot, \xi)$ is the loss of a data sample $\xi.$ In this paper we address the following natural setup:
\begin{itemize}
\item [(i)]  $n$ workers are available to  work in parallel,
\item [(ii)] the $i$\textsuperscript{th} worker requires $\tau_i$ seconds\footnote{Or any other unit of time.} to calculate a stochastic gradient of  $f$. 
\end{itemize}
The function $f$ is $L$--smooth and lower-bounded (see Assumptions~\ref{ass:lipschitz_constant}--\ref{ass:lower_bound}), and stochastic gradients are unbiased and $\sigma^2$-variance-bounded (see Assumption~\ref{ass:stochastic_variance_bounded}).





\subsection{Classical theory}
\label{sec:classical_theory}
In the nonconvex setting, gradient descent (GD)  is an optimal method with respect to the number of gradient ($\nabla f$) calls~\citep{lan2020first,nesterov2018lectures,carmon2020lower} for finding an approximately stationary point of $f$. Obviously, a key issue with GD is that it requires access to the exact gradients $\nabla f$ of the function $f.$ However, in many practical  applications, it can be infeasible to calculate  the gradient of $\Exp{f(\cdot;\xi)}$ analytically.  Moreover, even if this is possible, e.g., if the distribution $\mathcal{D}$ is described by $m$ possible samples, so that $\ExpSub{\xi \sim \mathcal{D}}{f(\cdot;\xi)} = (\nicefrac{1}{m}) \sum_{i=1}^m f(\cdot;\xi_i),$  $m$ can be huge \citep{krizhevsky2017imagenet}, and gradient evaluation can be arbitrarily expensive.

\textbf{Stochastic Gradient Descent.} Due to the above-mentioned problem, machine learning literature is preoccupied with the study of algorithms that can work with stochastic gradients instead~\citep{lan2020first, ghadimi2013stochastic}. For all $x \in \R^d,$ we assume that the $n$ workers have access to independent, unbiased, and $\sigma^2$-variance-bounded stochastic gradients $\widehat{\nabla} f(x, \xi)$ (see Assumption~\ref{ass:stochastic_variance_bounded}), where $\xi$ is a random sample from $\mathcal{D}$. Under such assumptions, {\bf with one worker}, stochastic gradient descent (SGD), i.e., the method $x^{k+1} = x^{k} - \gamma \widehat{\nabla} f(x^k; \xi^k),$ where $\xi^k$ are i.i.d. random samples from $\mathcal{D}$,
 is known to be  optimal  with respect to the number of stochastic gradient calls~\citep{ghadimi2013stochastic,arjevani2022lower}. SGD guarantees  convergence to an $\varepsilon$--stationary point in expectation after $\operatorname{O}\left(\nicefrac{L \Delta}{\varepsilon} + \nicefrac{\sigma^2 L \Delta}{\varepsilon^2}\right)$ stochastic gradient evaluations, where $\Delta \eqdef f(x^0) - f^*$ and $x^0 \in \R^d$ is a starting point.


\subsection{Parallel optimization methods}
\label{sec:previous_parallel_algorithms}
Using the bounds from Section~\ref{sec:classical_theory}, one can easily {\em estimate} the performance of these algorithms in real systems. For instance, if it takes $\tau_1$ \emph{seconds} to calculate a stochastic gradient {\bf with one worker}, then SGD guarantees to return a solution after $$\squeeze\operatorname{O}\left(\tau_1 \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{\varepsilon^2}\right)\right)$$ seconds. 
If  instead of a single worker we can access $n$ workers that can calculate stochastic gradients in parallel,
 we can consider the following classical parallel methods:

\textbf{Minibatch SGD.} The minibatch SGD method (Minibatch SGD), i.e., the iterative process $$\squeeze x^{k+1} = x^{k} - \gamma \frac{1}{n} \sum \limits_{i=1}^n \widehat{\nabla} f(x^k; \xi^k_i),$$ where $\gamma$ is a stepsize, $\xi^k_i$ are i.i.d.\ samples from $\mathcal{D},$ and the gradients $\widehat{\nabla} f(x^k; \xi^k_i)$ are calculated in parallel. This method converges after $\operatorname{O}\left(\nicefrac{L \Delta}{\varepsilon} + \nicefrac{\sigma^2 L \Delta}{n \varepsilon^2}\right)$ iterations \citep{cotter2011better, goyal2017accurate, gower2019sgd} and after 
\begin{align}
    \label{eq:mini_batch_compl}
    \squeeze
    \operatorname{O}\left(\tau_{\max} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right)
\end{align} seconds, where $\tau_{\max} \eqdef \max_{i \in [n]} \tau_i$ is the processing time associated with the \emph{slowest} machine\footnote{Further, we assume that the last $n$\textsuperscript{th} worker is the slowest one: $\tau_n = \tau_{\max}.$}.

Although the time complexity \eqref{eq:mini_batch_compl} of Minibatch SGD improves with the number of workers $n$, in general, this does {\em not} guarantee better performance due to the delay $\tau_{\max}$. In real systems, parallel computations can be very chaotic, e.g., they can be slow due to inconsistent network communications, or GPU computation delays \citep{dutta2018slow, chen2016revisiting}.

\textbf{Asynchronous SGD.} We now consider the asynchronous SGD method (Asynchronous SGD) \citep{recht2011hogwild, nguyen2018sgd, arjevani2020tight, feyzmahdavian2016asynchronous} described by
\begin{align*}
    &\textnormal{1. Receive } \widehat{\nabla} f(x^{k - \delta_k}; \xi^{k - \delta_k}) \textnormal{ from a worker},\\
& \textnormal{2. } x^{k+1} = x^{k} - \gamma^k \widehat{\nabla} f(x^{k - \delta_k}; \xi^{k - \delta_k}),\\
    &\textnormal{3. Ask the worker to calculate } \widehat{\nabla} f(x^{k+1}; \xi^{k+1}),
\end{align*} where $\xi^{k}$ are i.i.d.\ samples from $\mathcal{D},$ and $\delta_k$ are gradient iteration delays. This is an {\em asynchronous} method:  the workers work independently, finish calculations of stochastic gradients with potentially large and chaotic delays $\delta_k$, and the result of their computation is applied as soon as it is ready, without having to wait for other workers. Asynchronous SGD was also considered in the heterogeneous setting (see details in Section~\ref{sec:heterog_regime:related_work}).

\citet{cohen2021asynchronous, mishchenko2022asynchronous, koloskova2022sharper} provide the current state-of-the-art analysis of Asynchronous SGD. In particular, they prove that Asynchronous SGD converges after $\operatorname{O}\left(\nicefrac{n L \Delta}{\varepsilon} + \nicefrac{\sigma^2 L \Delta}{\varepsilon^2}\right)$ iterations. To show the superiority of Asynchronous SGD, \citet{mishchenko2022asynchronous} consider the following {\em fixed computation model}: the $i$\textsuperscript{th} worker requires $\tau_i$ seconds to calculate stochastic gradients. In this setting, Asynchronous SGD converges after
\begin{align}
    \label{eq:async_sgd_complexity}
    \squeeze
    \operatorname{O}\left(\left(\frac{1}{n} \sum \limits_{i=1}^n \frac{1}{\tau_i}\right)^{-1}\left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right)
\end{align} seconds (we reprove this fact in Section~\ref{sec:async_sgd_time}). Thus, Asynchronous SGD can be $(\nicefrac{1}{n}) \sum_{i=1}^n \nicefrac{\tau_{\max}}{\tau_i}$ times faster than Minibatch SGD.

Besides Asynchronous SGD, many other strategies utilize parallelization \citep{dutta2018slow, woodworth2020local, wu2022delay}, and can potentially improve over Minibatch SGD.

