\section{Heterogeneous Regime}
\label{sec:heterog_regime}

\begin{table*}
    \caption{\textbf{Heterogeneous Case.} The required time to get an $\varepsilon$-stationary point in the nonconvex setting, where $i$\textsuperscript{th} worker requires $\tau_i$ seconds to calculate a stochastic gradient. We assume that $0 < \tau_1 \leq \dots \leq \tau_n.$}
    \centering
