\end{table*}

Up to this point, we discussed the regime when all workers calculate i.i.d. stochastic gradients. In distributed optimization and federated learning \citep{konevcny2016federated}, it can be possible that the workers hold different datasets. Let us consider the following optimization problem:
\begin{align}
    \label{eq:main_task_heterog}
    \squeeze \min \limits_{x \in \R^d} \Big \{f(x) \eqdef \frac{1}{n} \sum_{i=1}^n \ExpSub{\xi_i \sim \mathcal{D}_i}{f_i(x;\xi_i)}\Big \},
\end{align}
where $f_i\,:\,\R^d \times \mathbb{S}_{\xi_i} \rightarrow \R^d$ and $\xi_i$ are random variables with some distributions $\mathcal{D}_i$ on $\mathbb{S}_{\xi_i}.$ Problem \eqref{eq:main_task_heterog} generalizes problem \eqref{eq:main_task}. Here we have the same goals as in the previous sections. We want to obtain the minimax complexities for the case when the workers contain different datasets.

\subsection{Lower bound}
For the heterogeneous case, we modify Definition~\ref{def:oracle_class}:
\begin{definition}[Oracle Class $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{\it heterog}}$]\ \\
    Let us consider an oracle class such that, for any $f = \frac{1}{n} \sum_{i=1}^n f_i \in \cF_{\Delta, L},$ it returns oracles $O_i = O_{\tau_i}^{\smallnablafunc_i}$ and distributions $\mathcal{D}_i$ for all $i \in [n],$ where $\widehat{\nabla} f_i$ is an unbiased $\sigma^2$-variance-bounded mapping for all $i \in [n]$ (see Assumption~\ref{ass:stochastic_variance_bounded}). The oracles $O_{\tau_i}^{\smallnablafunc_i}$ are defined in \eqref{eq:oracle_stochastic_delay}. We define such oracle class as $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{\it heterog}}.$ Without loss of generality, we assume that $0 < \tau_1 \leq \dots \leq \tau_n.$
\end{definition}

\begin{restatable}{theorem}{THEOREMLOWERBOUNDHETROG}
    \label{theorem:lower_bound_heterog}
    Let us consider the oracle class $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{\it heterog}}$ for some $\sigma^2 >0$ and $0 < \tau_1 \leq \dots \leq \tau_n.$ We fix any $L, \Delta > 0$ and $0 < \varepsilon \leq c' L \Delta.$ In the view Protocol~\ref{alg:time_multiple_oracle_protocol}, for any algorithm $A \in \cA_{\textnormal{zr}},$ there exists a function $f = \frac{1}{n} \sum_{i=1}^n f_i \in \cF_{\Delta, L}$ and oracles and distributions $((O_1, \dots, O_n), (\mathcal{D}_1, \dots, \mathcal{D}_n)) \in \cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{\it heterog}}(f_1, \dots, f_n)$
    such that
    $\Exp{\inf_{k \in S_t} \norm{\nabla f(x^k)}^2} > \varepsilon,$
    where $S_t \eqdef \left\{k \in \N_0 \middle| t^{k} \leq t\right\},$ and 
    \begin{align}
        \label{eq:lower_bound_heterog}
        \squeeze t = c \times \left(\tau_{n}\frac{L \Delta}{\varepsilon} + \left(\frac{1}{n} \sum_{i=1}^{n} \tau_i\right)\frac{\sigma^2 L \Delta}{n \varepsilon^2}\right).
    \end{align} The quantity $c'$ and $c$ are {\markchanges universal} constants.
\end{restatable}

Theorem~\ref{theorem:lower_bound_heterog} states that 
\begin{align*}
    \squeeze \mathfrak{m}_{\textnormal{time}}\left(\cA_{\textnormal{zr}}, \cF_{\Delta, L}\right) = \Omega\left(\tau_{n}\frac{L \Delta}{\varepsilon} + \left(\frac{1}{n} \sum_{i=1}^{n} \tau_i\right)\frac{\sigma^2 L \Delta}{n \varepsilon^2}\right).
\end{align*}

One can see that the lower bound for the heterogeneous case is larger than \eqref{eq:lower_complexity_lower_bound}. 
In Section~\ref{sec:heterog}, we provide a method that attains the lower bound.

\subsection{Related work and discussion}
\label{sec:heterog_regime:related_work}
The optimization problem \eqref{eq:main_task_heterog} is well-investigated by many papers, including \citep{aytekin2016analysis, mishchenko2018delay, nguyen2022federated, wu2022delay, koloskova2022sharper, mishchenko2022asynchronous}. There were attempts to analyze Asynchronous SGD in the heterogeneous regime. For instance, \citet{mishchenko2022asynchronous} proved the convergence to a neighborhood of a solution only. In general, it is quite challenging to get good rates for Asynchronous SGD without additional assumptions about the similarity of the functions $f_i$ \citep{koloskova2022sharper, mishchenko2022asynchronous}.

In the non-stochastic case, when $\sigma^2 = 0,$ \citet{wu2022delay} analyzed the PIAG method in the non-stochastic heterogeneous regime and showed convergence. Although the performance of PIAG can be good in practice, in the worst case PIAG requires $\operatorname{O}\left(\nicefrac{\tau_{n} \widehat{L} \Delta}{\varepsilon}\right)$ seconds to converge, where $\tau_{n}$ is the time delay of the slowest worker, $\widehat{L} \eqdef \sqrt{\sum_{i=1}^n L_i^2},$ and $L_i$ is a Lipschitz constant of $\nabla f_i.$ Note that the synchronous Minibatch SGD (see Section~\ref{sec:previous_parallel_algorithms}) method has the complexity $\operatorname{O}\left(\nicefrac{\tau_{n} L \Delta}{\varepsilon}\right),$ which is always better.\footnote{In the nonconvex case, $\widehat{L}$ can be arbitrarily larger than $L.$} 

Our lower bound in Theorem~\ref{theorem:lower_bound_heterog} does not leave hope of breaking the dependence on the worst straggler in the heterogeneous case. In the stochastic case, the lower bound is slightly more optimistic in the regimes when the statistical term (the second term in \eqref{eq:lower_bound_heterog}) is large. If the stragglers do not have too large delays, then their contributions to the \emph{arithmetic} mean can be small. Note that in Theorem~\ref{theorem:lower_bound_homog} in the homogeneous case, we have the \emph{harmonic} mean of the delays instead.

\subsection{Minimax optimal method}
\label{sec:heterog}
In this section, we provide Malenia\footnote{\tiny\url{https://eldenring.wiki.fextralife.com/Malenia+Blade+of+Miquella}: Malenia, Blade of Miquella and Malenia, Goddess of Rot is two-phase a Demigod Boss in Elden Ring. She's the twin of Miquella, the most powerful of the Empyreans, and gained renown for her legendary battle against Starscourge Radahn during the Shattering, in which she unleashed the power of the Scarlet Rot and reduced Caelid to ruins.} SGD (see Method~\ref{alg:alg_server_heterog}) that is slightly different from Rennala SGD (Method~\ref{alg:alg_server}). There are two main differences: the first one is that Method~\ref{alg:alg_server_heterog} has different gradients estimators $g^k_i$ for each worker, and the second one is the constraint $\left(\frac{1}{n} \sum_{i=1}^n \nicefrac{1}{B_i}\right)^{-1} < \nicefrac{S}{n}$ in the inner loop\footnote{We assume that $\left(\frac{1}{n} \sum_{i=1}^n \nicefrac{1}{B_i}\right)^{-1} = 0$ if exists $i \in [n]$ such that $B_i = 0.$}. The more gradients we get from the workers, the larger the term $\left(\frac{1}{n} \sum_{i=1}^n \nicefrac{1}{B_i}\right)^{-1}.$
\begin{method}
    \caption{Malenia SGD}
    \label{alg:alg_server_heterog}
    \begin{algorithmic}[1]
    \STATE \textbf{Input:} starting point $x^0$, stepsize $\gamma$, parameter $S$
    \STATE Run Method~\ref{alg:alg_worker_heterog} in all workers
    \FOR{$k = 0, 1, \dots, K - 1$}
    \STATE Init $g^k_i = 0$ and $B_i = 0$
    \WHILE{$\left(\frac{1}{n} \sum_{i=1}^n \frac{1}{B_i}\right)^{-1} < \frac{S}{n}$}
    \STATE Wait for the next worker
    \STATE Receive gradient, iteration index, worker's index $(g, k', i)$
    \IF{$k' = k$}
    \STATE $g^k_i = g^k_i + g$
    \STATE $B_i = B_i + 1$
    \ENDIF
    \STATE Send $(x^k, k)$ to the worker
    \ENDWHILE
    \STATE $g^{k} = \frac{1}{n} \sum_{i=1}^n \frac{1}{B_i} g^k_i$
    \STATE $x^{k+1} = x^k - \gamma g^{k}$
    \ENDFOR
    \end{algorithmic}
\end{method}

\begin{method}
    \caption{Worker's Infinite Loop}
    \label{alg:alg_worker_heterog}
    \begin{algorithmic}[1]
    \STATE Init $g = 0,$ $k' = -1,$ and worker's index $i$
    \WHILE{True}
    \STATE Send $(g, k', i)$ to the server
    \STATE Receive $(x^k, k)$ from the server
    \STATE $k' = k$
    \STATE $g = \widehat{\nabla} f_i(x^k;\xi), \quad \xi \sim \mathcal{D}$
    \ENDWHILE
    \end{algorithmic}
\end{method}

As in Section~\ref{sec:analysis_homog}, we can provide the convergence theorems.

\begin{restatable}{theorem}{THEOREMSGDHETROG}
    \label{thm:sgd_heterog}
    Assume that Assumptions~\ref{ass:lipschitz_constant} and \ref{ass:lower_bound} hold for the function $f$. Assumption \ref{ass:stochastic_variance_bounded} holds for the function $f_i$ for all $i \in [n].$ Let us take the parameter $S = \max\left\{\left\lceil\nicefrac{\sigma^2}{\varepsilon}\right\rceil, n\right\},$ and
    $\gamma = \min\left\{\frac{1}{L}, \frac{\varepsilon S}{2 L \sigma^2}\right\} = \Theta\left(\nicefrac{1}{L}\right)$ in Method~\ref{alg:alg_server_heterog},
    then after $K \geq \nicefrac{24 \Delta L}{\varepsilon}$
    iterations the method guarantees that $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\norm{\nabla f(x^k)}^2} \leq \varepsilon.$
\end{restatable}

\begin{restatable}{theorem}{THEOREMSGDHETROGTIME}
    \label{theorem:heterog_time}
        Let us consider Theorem~\ref{thm:sgd_heterog}. We assume that $i$\textsuperscript{th} worker returns a stochastic gradient every $\tau_i$ seconds for all $i \in [n]$. Without loss of generality, we assume that $0 < \tau_1 \leq \cdots \leq \tau_n.$ Then after
        \begin{align}
            \label{eq:compl_heterog}
            \squeeze 96\left(\tau_{n}\frac{L \Delta}{\varepsilon} + \left(\frac{1}{n} \sum_{i=1}^n \tau_i\right) \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)
        \end{align}
        seconds, Method~\ref{alg:alg_server_heterog} guarantees to find an $\varepsilon$-stationary point.
\end{restatable}
Comparing Theorem~\ref{theorem:lower_bound_heterog} and Theorem~\ref{theorem:heterog_time}, one can see that the complexity \eqref{eq:compl_heterog} is optimal. Note that Theorem~\ref{thm:sgd_heterog} holds without assumptions that the delays $\tau_i$ are fixed.

\subsection{Discussion}
Unlike Asynchronous SGD and PIAG, Malenia SGD ignores all stochastic gradients that were calculated in the previous iterations, which appears to be counterproductive. Nevertheless, we show that Malenia SGD converges, and the time complexity is optimal with respect to all parameters. Note that Malenia SGD does not require the Lipschitz smoothness of the local functions $f_i,$ does not depend on the time delays $\tau_i,$ does not need any similarity assumptions about the functions $f_i,$ and can be applied to problems where the function is not Lipschitz (does not have bounded gradients). The analysis of the method is elementary and does not go far away from the theory of the classical SGD method. When the ratio $\nicefrac{\sigma^2}{\varepsilon}$ is large, Malenia SGD is better than Minibatch SGD (see \eqref{eq:mini_batch_compl}) by $\Theta\left(\tau_n / \left(\frac{1}{n} \sum_{i=1}^n \tau_i\right)\right)$ times.

\section{Convex Case}
\label{sec:convex_case}

\subsection{Lower Bound}

Let us consider the optimization problem \eqref{eq:main_task} in the case when the function $f$ is convex. For the convex case, using Protocol~\ref{alg:time_oracle_protocol}, we propose to use another complexity measure instead of \eqref{eq:lower_compl_time}:
\begin{align}\label{eq:lower_compl_time_convex}
    \begin{split}
    \squeeze
    &\mathfrak{m}_{\textnormal{time}}\left(\cA, \cF\right) \eqdef \inf_{A \in \cA} \sup_{f \in \cF} \sup_{(O, \mathcal{D}) \in \cO(f)} \inf\left\{t \geq 0\,\middle|\,\Exp{ \inf_{k \in S_t}f(x^k)} - \inf_{x \in Q} f(x) \leq \varepsilon \right\}, 
    \\
    &S_t \eqdef \left\{k \in \N_0 \middle| t^{k} \leq t\right\},
\end{split}
\end{align}
where the sequences $t^k$ and $x^k$ are generated by Protocol~\ref{alg:time_oracle_protocol}. Let us consider the following class of convex functions:
\begin{definition}[Function Class $\cF^{\textnormal{conv}}_{R, M, L}$]\ \\
    \leavevmode
    Let us define $B_2(0, R) \eqdef \left\{x \in \R^d\,|\,\norm{x} \leq R\right\}.$ We assume that a function $f \,:\,\R^d \rightarrow \R$ is convex, differentiable, $L$-smooth on the set $B_2(0, R)$, i.e.,
    \begin{align*}
        \norm{\nabla f(x) - \nabla f(y)} \leq L \norm{x - y} \quad \forall x, y \in B_2(0, R),
    \end{align*}
    and $M$-Lipschitz on the set $B_2(0, R)$, i.e.,
    \begin{align*}
        |f(x) - f(y)| \leq M \norm{x - y} \quad \forall x, y \in B_2(0, R).
    \end{align*}
    A set of all functions with such properties we define as $\cF^{\textnormal{conv}}_{R, M, L}.$
    \label{def:func_class_convex}
\end{definition}
For the convex case, we analyze the following class of algorithms:

