\begin{restatable}{theorem}{THEOREMLOWERBOUNDCONVEX}
    \label{theorem:lower_bound_homog_convex}
    Let us consider the oracle class $\cO_{\tau_1, \dots, \tau_n}^{\textnormal{conv}, \sigma^2}$ for some $\sigma^2 >0$ and $0 < \tau_1 \leq \dots \leq \tau_n.$ We fix any $R, L, M, \varepsilon > 0$ such that $\sqrt{L} R > c_1 \sqrt{\varepsilon} > 0$ and $M^2 R^2 > c_2 \varepsilon^2.$ In the view Protocol~\ref{alg:time_multiple_oracle_protocol}, for any algorithm $A \in \cA^{R}_{\textnormal{zr}},$ there exists a function $f \in \cF^{\textnormal{conv}}_{R, M, L}$ and oracles and distributions $((O_1, \dots, O_n), (\mathcal{D}_1, \dots, \mathcal{D}_n)) \in \cO_{\tau_1, \dots, \tau_n}^{\textnormal{conv}, \sigma^2}(f)$
    such that
        $$\Exp{ \inf_{k \in S_t}f(x^k)} - \inf_{x \in B_2(0, R)} f(x) > \varepsilon,$$
    where $S_t \eqdef \left\{k \in \N_0 \middle| t^{k} \leq t\right\},$ and $$ t = c \times \min \limits_{m \in [n]} \left[\left(\frac{1}{m} \sum \limits_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\min\left\{\frac{\sqrt{L} R}{\sqrt{\varepsilon}}, \frac{M^2 R^2}{\varepsilon^2}\right\} + \frac{\sigma^2 R^2}{m \varepsilon^2}\right)\right] .$$ The quantities $c_1,$ $c_2$ and $c$ are {\markchanges universal} constants.
\end{restatable}

\subsubsection{Discussion}
\label{sec:convex_dis}
We improve the lower bound obtained by \citep{woodworth2018graph} (see Table~\ref{table:complexities_convex}).  \citet{woodworth2018graph} try to reduce any optimization problem to an oracle graph. Then, they get a lower bound using the depth and the number of nodes in a graph. Our approach is different, as we directly estimate the required time and avoid the reduction to an oracle graph. 
One can think that our ``oracle graph'' is always linear in Protocol~\ref{alg:time_multiple_oracle_protocol}, but every node in an ``oracle graph'' is associated with a timestamp and an index. Unlike the oracle in \citep{woodworth2018graph}, which always returns a stochastic gradient, our oracle \eqref{eq:oracle_stochastic_delay} returns a stochastic gradient only if the conditions are satisfied.
Also, \citet{woodworth2018graph} construct different ``worst case'' functions and oracles for the ``optimization'' and ``statistical'' terms. While our construction
consists only of one function and one oracle. 

\subsection{Minimax optimal method}
\label{sec:minimax_optimal_homog_convex}

\subsubsection{Assumptions}

Additionally to some assumptions from Section~\ref{sec:assumption}, we use the following assumptions in the convex case.

\begin{assumption}
    \label{ass:convex}
    The function $f$ is convex and attains the minimum at some point $x^* \in \R^d.$
\end{assumption}


\begin{assumption}
    \label{ass:lipschitz_constant_function}
    The function $f$ is $M$--Lipschitz, i.e., $$\abs{f(x) - f(y)} \leq M \norm{x - y}, \quad \forall x, y \in \R^d.$$
\end{assumption}

\begin{assumption}
    \label{ass:stochastic_variance_bounded_convex}
    For all $x \in \R^d,$ stochastic gradients $\widehat{\nabla} f(x;\xi)$ are unbiased and have $\sigma^2$-variance-bounded, i.e.,
    $\ExpSub{\xi \sim \mathcal{D}}{\widehat{\nabla} f(x;\xi)} \in \partial f(x)$ and 
    $\ExpSub{\xi \sim \mathcal{D}}{\norm{\widehat{\nabla} f(x;\xi) - \Exp{\widehat{\nabla} f(x;\xi)}}^2} \leq \sigma^2,$ where $\sigma^2 \geq 0.$
\end{assumption} 

