\section{Proofs for Homogeneous Regime}

\subsection{The ``worst case'' function}
\label{sec:worst_case}
In this section, we recall the ``worst case'' function that we use to prove our lower bounds. This is the standard function that is used in nonconvex optimization. Let us define
\begin{align*}
    \textnormal{prog}(x) \eqdef \max \{i \geq 0\,|\,x_i \neq 0\} \quad (x_0 \equiv 1).
\end{align*}

In our proofs, we use the construction from \citep{carmon2020lower,arjevani2022lower}. For any $T \in \N,$ the authors define
\begin{align}
    \label{eq:worst_case}
    F_T(x) \eqdef -\Psi(1) \Phi(x_1) + \sum_{i=2}^T \left[\Psi(-x_{i-1})\Phi(-x_i) - \Psi(x_{i-1})\Phi(x_i)\right],
\end{align}
where
\begin{align*}
    \Psi(x) = \begin{cases}
        0, & x \leq 1/2, \\
        \exp\left(1 - \frac{1}{(2x - 1)^2}\right), & x \geq 1/2,
    \end{cases}
    \quad\textnormal{and}\quad
    \Phi(x) = \sqrt{e} \int_{-\infty}^{x}e^{-\frac{1}{2}t^2}dt.
\end{align*}

The main property of the function $F_T(x)$ is that its gradients are large unless $\textnormal{prog}(x) \geq T.$

\begin{lemma}[\cite{carmon2020lower, arjevani2022lower}]
    \label{lemma:worst_function}
    The function $F_T$ satisfies:
    \begin{enumerate}
        \item $F_T(0) - \inf_{x \in \R^T} F_T(x) \leq \Delta^0 T,$ where $\Delta^0 = 12.$
        \item The function $F_T$ is $l_1$--smooth, where $l_1 = 152.$
        \item For all $x \in \R^T,$ $\norm{\nabla F_T(x)}_{\infty} \leq \gamma_{\infty},$ where $\gamma_{\infty} = 23.$
        \item For all $x \in \R^T,$ $\textnormal{prog}(\nabla F_T(x)) \leq \textnormal{prog}(x) + 1.$
        \item For all $x \in \R^T,$ if $\textnormal{prog}(x) < T,$ then $\norm{\nabla F_T(x)} > 1.$
    \end{enumerate}
\end{lemma}

We use these properties in the proofs.

\subsection{Proof of Theorem~\ref{theorem:lower_bound_homog}}
\THEOREMLOWERBOUND*

Before we prove the theorem, let us briefly explain the idea. In Steps 1 and 2 of the proof, we construct the appropriate scaled function and stochastic oracles using the function \eqref{eq:worst_case}. These steps are almost the same as in \citep{carmon2020lower, arjevani2022lower}. 

In Step 3, we use the zero-chain property of the function \eqref{eq:worst_case} and the zero-respecting property of algorithms that would guarantee us that unless oracles send us a non-zero coordinate, an algorithm would not be able to progress to a new coordinate. The oracles send a non-zero coordinate with some probability $p$. We have $n$ parallel oracles that flip random coins \emph{in parallel}. With a large probability, we show that will \emph{not} get a new coordinate earlier than $$\approx \min \limits_{m \in [n]} \left[\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + m\right)\right]$$ seconds, where $\tau_i$ are the delays of the oracles. So, with a large probability, we will not be able to solve the optimization earlier than 
$$\approx T \times \min \limits_{m \in [n]} \left[\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + m\right)\right],$$ where $T$ is the dimension of the problem.

\begin{proof}
    (\textbf{Step 1}: $f \in \cF_{\Delta, L}$)

    Let us fix $\lambda > 0$ and take a function $f(x) \eqdef L \lambda^2 / l_1 F_T\left(\frac{x}{\lambda}\right),$  where the function $F_T$ is defined in Section~\ref{sec:worst_case}. Note that the function $f$ is $L$-smooth: 
    \begin{align*}
        \norm{\nabla f(x) - \nabla f(y)} = L \lambda / l_1 \norm{F_T\left(\frac{x}{\lambda}\right) - F_T\left(\frac{y}{\lambda}\right)} \leq L \lambda \norm{\frac{x}{\lambda} - \frac{y}{\lambda}} = L \norm{x - y} \quad \forall x, y \in \R^d.
    \end{align*}
    Let us take $$T = \left\lfloor\frac{\Delta l_1}{L \lambda^2 \Delta^0}\right\rfloor,$$ then
    \begin{align*}
        f(0) - \inf_{x \in \R^T} f(x) = \frac{L \lambda^2}{l_1} (F_T\left(0\right) - \inf_{x \in \R^T} F_T(x)) \leq \frac{L \lambda^2 \Delta^0 T}{l_1} \leq \Delta.
    \end{align*}
    We showed that the function $f \in \cF_{\Delta, L}.$

    (\textbf{Step 2}: Oracle Class)

    In the oracles $O_i,$ we have the freedom to choose a mapping $\widehat{\nabla} f(\cdot; \cdot)$ (see \eqref{eq:oracle_stochastic_delay}). Let us take 
    \begin{align*}[\widehat{\nabla} f(x; \xi)]_j \eqdef \nabla_j f(x) \left(1 + \mathbbm{1}\left[j > \textnormal{prog}(x)\right]\left(\frac{\xi}{p} - 1\right)\right) \quad \forall x \in \R^T,\end{align*} and $\mathcal{D}_i = \textnormal{Bernouilli}(p)$ for all $i \in [n],$ where $p \in (0, 1].$ We denote $[x]_j$ as the $j$\textsuperscript{th} index of a vector $x \in \R^T.$
It is left to show this mapping is unbiased and $\sigma^2$-variance-bounded. Indeed, $$\Exp{[\widehat{\nabla} f(x, \xi)]_i} = \nabla_i f(x) \left(1 + \mathbbm{1}\left[i > \textnormal{prog}(x)\right]\left(\frac{\Exp{\xi}}{p} - 1\right)\right) = \nabla_i f(x)$$ for all $i \in [T],$ and
\begin{align*}
    \Exp{\norm{\widehat{\nabla} f(x; \xi) - \nabla f(x)}^2} \leq \max_{j \in [T]} \left|\nabla_j f(x)\right|^2\Exp{\left(\frac{\xi}{p} - 1\right)^2}
\end{align*}
because the difference is non-zero only in one coordinate. Thus
\begin{align*}
    \Exp{\norm{\widehat{\nabla} f(x, \xi) - \nabla f(x)}^2} &\leq \frac{\norm{\nabla f(x)}_{\infty}^2(1 - p)}{p} = \frac{L^2 \lambda^2 \norm{F_T\left(\frac{x}{\lambda}\right)}_{\infty}^2(1 - p)}{l_1^2 p} \\
    &\leq \frac{L^2 \lambda^2 \gamma_{\infty}^2 (1 - p)}{l_1^2 p} \leq \sigma^2,
\end{align*}
where we take 
$$p = \min\left\{\frac{L^2 \lambda^2 \gamma_{\infty}^2}{\sigma^2 l_1^2}, 1\right\}.$$

(\textbf{Step 3}: Analysis of Protocol)

We choose 
$$\lambda = \frac{\sqrt{2 \varepsilon} l_1}{L}$$
to ensure that $\norm{\nabla f(x)}^2 = \frac{L^2 \lambda^2}{l_1^2}\norm{\nabla F_T (\frac{x}{\lambda})}^2 > 2 \varepsilon \mathbbm{1}\left[\textnormal{prog}(x) < T\right]$ for all $x \in \R^T,$ where we use Lemma~\ref{lemma:worst_function}. Thus
$$T = \left\lfloor\frac{\Delta L}{2 \varepsilon l_1 \Delta^0}\right\rfloor$$
and
$$p = \min\left\{\frac{2 \varepsilon \gamma_{\infty}^2}{\sigma^2}, 1\right\}.$$



Protocol~\ref{alg:time_multiple_oracle_protocol} generates a sequence $\{x^k\}_{k=0}^{\infty}.$ We have
\begin{align}
    \label{eq:aux_part_3_homog}
    \inf_{k \in S_t} \norm{\nabla f(x^k)}^2 > 2 \varepsilon \inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right].
\end{align}


Using Lemma~\ref{lemma:boundtime} with $\delta = 1/2$ and \eqref{eq:aux_part_3_homog}, we obtain
\begin{align*}
    \Exp{\inf_{k \in S_t} \norm{\nabla f(x^k)}^2} &\geq 2 \varepsilon \Prob{\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] \geq 1} > \varepsilon
\end{align*}
for $$t = \frac{1}{24} \min_{m \in [n]} \left[\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{\sigma^2}{2 \varepsilon \gamma_{\infty}^2} + m\right)\right] \left(\frac{\Delta L}{2 \varepsilon l_1 \Delta^0} - 2\right).$$

\end{proof}

\subsection{Auxillary lemmas}
\label{sec:aux_lemmas}

\subsubsection{Proof of Lemma~\ref{lemma:boundtime}}

\begin{restatable}{lemma}{LEMMABOUNDTIME}
    \label{lemma:boundtime}
    Let us fix $T, T' \in \N$ such that $T \leq T'$, consider Protocol~\ref{alg:time_multiple_oracle_protocol} with a differentiable function $f\,:\,\R^{T'} \rightarrow \R$ such that $\textnormal{prog}(\nabla f(x)) \leq \textnormal{prog}(x) + 1$ for all $x \in \textnormal{domain}(f),$ delays $0 < \tau_1 \leq \dots \leq \tau_n,$ distributions $\mathcal{D}_i = \textnormal{Bernouilli}(p)$ and oracles $O_i = O_{\tau_i}^{\smallnablafunc}$ for all $i \in [n],$ mappings 
    \begin{align}
        \label{eq:proof_stoch_grad_lemma}
        [\widehat{\nabla} f(x; \xi)]_j = \nabla_j f(x) \left(1 + \mathbbm{1}\left[j > \textnormal{prog}(x)\right]\left(\frac{\xi}{p} - 1\right)\right) \quad \forall x \in \R^{T'}, \forall \xi \in \{0, 1\}, \forall j \in [T],
    \end{align}
    and an algorithm $A \in \cA_{\textnormal{zr}}.$  With probability not less than $1 - \delta,$
    \begin{align*}
        \inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] \geq 1
    \end{align*}
    for $$t \leq \frac{1}{24} \min_{m \in [n]} \left[\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + m\right)\right] \left(\frac{T}{2} + \log \delta\right),$$
    where the iterates $x^k$ are defined in Protocol~\ref{alg:time_multiple_oracle_protocol}.
\end{restatable}

\begin{proof}



    \textbf{(Part 1):} \emph{Comment: in this part, we formally show that if $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, then we have the inequality $\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq t$, where $\widehat{t}_{\eta_{i}}$ are random variables with some known ``good'' distributions. If $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1,$ then it means that exists $k$ such that $\textnormal{prog}(x^k) = T.$ Note that the algorithm is zero-respecting, so it can not progress to $T$\textsuperscript{th} coordinate unless the oracles generate stochastic gradients with non-zero $1$\textsuperscript{st}, $2$\textsuperscript{nd}, ..., $T$\textsuperscript{th} coordinates. The oracles flip coins in parallel, so the algorithm should wait for the moment when the oracles flip a success. At the same time, it takes time to generate a coin (calculate a stochastic gradient), and the oracles can not flip more than $k$ coins before some time $\widehat{t}_{k}.$ So if the $\eta_{i}$ is an index of the first success to generate a non-zero $i$\textsuperscript{th} coordinate, then the algorithm should wait at least $\widehat{t}_{\eta_{i}}$ seconds. Next, we give a formal proof.}

    Let us fix $t \geq 0$ and define the smallest index $k(i)$ of the sequence when the progress $\textnormal{prog}(x^{k(i)})$ equals $i:$
    \begin{align*}
        k(i) \eqdef \inf\left\{k \in \N_0\,|\, i = \textnormal{prog} (x^k)\right\} \in \N_0 \cup \{\infty\}.
    \end{align*}

    If $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, then exists $k \in S_t$ such that $\textnormal{prog} (x^{k}) = T,$ thus, by the definition of $k(T),$ $t^{k(T)} \leq t^{k} \leq t,$ and $k(T) < \infty.$ Note that $t^{k(T)}$ is the smallest time when we make progress to the $T$\textsuperscript{th} coordinate.

    Since $x^0 = 0$ and $A$ is a zero-respecting algorithm, the algorithm can return a vector $x^k$ with the non-zero first coordinate only if some of returned by the oracles stochastic gradients have the first coordinate not equal to zero. The oracles $O_i$ are constructed in such a way (see \eqref{eq:proof_stoch_grad_lemma} and \eqref{eq:oracle_stochastic_delay}) that they zero out a coordinate based on i.i.d. Bernoulli trials. 


    \begin{definition}[Sequence $k^{\xi}_j$]
    Let us consider a set
    \begin{align*}
        \{k \in \N \,|\, s^{k-1}_{{i^{k}}, q} = 1 \textnormal{ and } t^{k} \geq s^{k-1}_{{i^{k}}, t} + \tau_{i^{k}}\}, \quad s^{k-1}_{{i^{k}}} \equiv (s^{k-1}_{{i^{k}}, t}, s^{k-1}_{{i^{k}}, q}, s^{k-1}_{{i^{k}}, x}).
    \end{align*}
    We order this set and define the result sequence as $\{k^{\xi}_j\}_{j=1}^m,$ where $m \in [0, \infty]$ is the size of the sequence. The sequence $k^{\xi}_i$ is a subsequence of iterations where the oracles use the generated Bernouilli random variables in the third output of \eqref{eq:oracle_stochastic_delay}. The sequence $s^{k-1}_{{i^{k}}}$ is defined in Protocol~\ref{alg:time_multiple_oracle_protocol}.
    \end{definition}

    Let $k_{\textnormal{success}}$ be the \emph{first} iteration index when the oracles use a draw $\xi = 1,$ i.e., $$k_{\textnormal{success}} \eqdef \inf \{k\,|\, \xi^k = 1 \textnormal{ and } k \in \{k^{\xi}_j\}_{j=1}^{m}\} \in \N \cup \{\infty\}.$$ 
    Since the algorithm $A$ is a zero-respecting and the function $f$ is a zero-chain function, i.e., $\textnormal{prog}(\nabla f(x)) \leq \textnormal{prog}(x) + 1$ for all $x \in \textnormal{domain}(f),$ then $\textnormal{prog}(g^k) = \textnormal{prog}(x^k) = 0$ for all $k < k_{\textnormal{success}}.$ If $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, then $k_{\textnormal{success}} < \infty,$ and $t^{{k_{\textnormal{success}}}} \leq t^{k(1)}.$



    The oracles use the generated Bernoulli random variables $\{\xi^{k} \,|\, k \in \{k^{\xi}_j\}_{j=1}^{m}\}$. Let us denote the index of the first successful trial as $\eta_1,$ i.e., $$\eta_1 \eqdef \inf \{i \,|\, \xi^{k^{\xi}_i} = 1 \textnormal{ and } i \in [1, m]\} \in \N \cup \{\infty\}.$$ The $i$\textsuperscript{th} worker can generate the first Bernoulli random variable not earlier than after $\tau_i$ seconds, the second Bernoulli random variable not earlier than after $2\tau_i$ seconds, and so forth. 

    \begin{definition}[Sequence $\widehat{t}_k$]
    \label{def:time_seq}
    Let us consider a \emph{multi-set} of times $$\{j \tau_i\,|\, j \geq 1, i \in [n]\} \equiv \{\tau_1, 2 \tau_1, \dots\} \uplus \dots \uplus \{\tau_n, 2 \tau_n, \dots\}.$$ We order this multi-set and define the result sequence as $\{\widehat{t}_k\}_{k=1}^{\infty},$ and $\widehat{t}_{\infty} \eqdef \lim_{k \rightarrow \infty} \widehat{t}_{k} = \infty.$
    \end{definition}

    Then $\eta_1$\textsuperscript{th} Bernoulli random variable can not be generated earlier than $\widehat{t}_{\eta_1}$ because $\widehat{t}_{\eta_1}$ is the earliest time when the oracles can generate $\eta_1$ random variables. Therefore, if $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, then $\widehat{t}_{\eta_1} \leq t^{k_{\textnormal{success}}} \leq t^{k(1)}.$

    Using the same reasoning, $t^{k(j+1)} \geq t^{k(j)} + \widehat{t}_{\eta_{j+1}},$ where $\eta_{j+1}$ is the index of the first successful trial of Bernouilli random variables when $\textnormal{prog}(\cdot) = j$ in the sequence $x^k$. More formally:


    \begin{definition}[Sequence $k^{\xi}_{j,i}$]
        Let us consider a set
        \begin{align*}
            \{k \in \N \,|\, s^{k-1}_{{i^{k}}, q} = 1 \textnormal{ and } t^{k} \geq s^{k-1}_{{i^{k}}, t} + \tau_{i^{k}} \textnormal{ and } \textnormal{prog}(s^{k-1}_{{i^{k}}, x}) = j\}.
        \end{align*}
        We order this set and define the result sequence as $\{k^{\xi}_{j,i}\}_{i=1}^{m_{j+1}},$ where $m_{j+1} \in [0, \infty]$ is the size of the sequence. The sequence $k^{\xi}_{j,i}$ is a subsequence of iterations where the oracles use the generated Bernouilli random variables in \eqref{eq:oracle_stochastic_delay} when $\textnormal{prog}(s_x) = j.$
    \end{definition}

    Then 
    \begin{align}
        \label{eq:geom_dist}
        \eta_{j+1} \eqdef \inf \{i \,|\, \xi^{k^{\xi}_{j,i}} = 1 \textnormal{ and } i \in [1, m_{j+1}]\} \in \N \cup \{\infty\} \quad \forall j \in \{0, \dots, T-1\}.
    \end{align}
    By the definition of $k(j),$ $x^{k(j)}$ is the first vector of the sequence, that contains a non-zero $j$\textnormal{th} coordinate. Thus the oracles will start returning stochastic gradients that potentially have a non-zero $j+1$\textsuperscript{th} coordinate starting only from the iteration $k(j).$ Therefore, $$t^{k(T)} \geq t^{k(T-1)} + \widehat{t}_{\eta_{T}} \geq \sum_{i=1}^T \widehat{t}_{\eta_{i}}.$$

    Combining the observations, if $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, then 
    $\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq t^{k(T)} \leq t.$ Thus
    \begin{align*}
        \Prob{\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1} \leq \Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq t} \quad \forall t \geq 0.
    \end{align*}


    In Section~\ref{sec:lemma_probs}, we prove the following inequality that we use in Part 2 of the proof.

    \begin{restatable}{lemma}{LEMMAPROBS}
        \label{lemma:probs}
        Let us take $l_{j+1} \in \N.$ Then
        \begin{align*}
            \ProbCond{\eta_{j+1} = l_{j+1}}{\eta_{j}, \dots, \eta_{1}} \leq (1 - p)^{l_{j+1} - 1}p
        \end{align*}
        for all $j \in \{0, \dots, T-1\}.$
    \end{restatable}

    \textbf{(Part 2):} \emph{Comment: in this part, we use the standard technique to bound the large deviations of the sum $\sum_{i=1}^T \widehat{t}_{\eta_{i}}$.}





    Let us fix $t' \geq 0.$ Recall Definition~\ref{def:time_seq} of $\{\widehat{t}_k\}_{k=1}^{\infty}.$ If the number of workers $n = 1,$ then $\widehat{t}_k = k\tau_1$ for all $k \geq 1.$ For $n > 1,$ the sequence $\{\widehat{t}_k\}_{k=1}^{\infty}$ has more complicated structure and depends on the delays $\tau_1, \dots, \tau_n.$ 

    For any $k \geq 1,$ if $\widehat{t}_{k} \leq t',$ then $k \leq \sum_{i = 1}^{n} \lfloor \frac{t'}{\tau_i}\rfloor.$ Indeed, let us assume that $k > \sum_{i = 1}^{n} \lfloor \frac{t'}{\tau_i}\rfloor.$ The sequence $\widehat{t}_{k}$ is constructed by the ordering the multi-set $\{j \tau_i\,|\, j \geq 1, i \in [n]\}.$ The number of elements, which are less or equal to $t',$ equals $\sum_{i = 1}^{n} \lfloor \frac{t'}{\tau_i}\rfloor.$ Thus, we get a contradiction. 

    It means that
    \begin{align*}
        \ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} \leq \ProbCond{\eta_{j+1} \leq \sum_{i = 1}^{n} \left\lfloor \frac{t'}{\tau_i}\right\rfloor}{\eta_{j}, \dots, \eta_{1}}.
    \end{align*}
    Using Lemma~\ref{lemma:probs}, we have
    \begin{align*}
        \ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} \leq \sum_{j=1}^{\sum_{i = 1}^{n} \left\lfloor \frac{t'}{\tau_i}\right\rfloor} (1 - p)^{j - 1} p.
    \end{align*}
    If $0 \leq t' < \tau_1,$ then $\sum_{i = 1}^{n} \left\lfloor \nicefrac{t'}{\tau_i}\right\rfloor = 0,$ and
    \begin{align*}
        \ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} = 0.
    \end{align*}
    Otherwise, if $t' > \tau_1,$ then $\sum_{i = 1}^{n} \left\lfloor \nicefrac{t'}{\tau_i}\right\rfloor \geq 1,$
    and
    \begin{align*}
        \ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} \leq 1 - (1 - p)^{\sum_{i = 1}^{n} \left\lfloor \frac{t'}{\tau_i}\right\rfloor} \leq p \sum_{i = 1}^{n} \left\lfloor \frac{t'}{\tau_i}\right\rfloor,
    \end{align*}
    where we use the fact that $1 - (1 - p)^m \leq p m$ for all $p \in [0, 1]$ and $m \in \N.$ For all $t' \geq 0,$ we have
    \begin{align*}
        \ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} \leq p \sum_{i = 1}^{n} \left\lfloor \frac{t'}{\tau_i}\right\rfloor.
    \end{align*}

    Let us define $$p' \eqdef p \sum_{i = 1}^{n} \left\lfloor \frac{t'}{\tau_i}\right\rfloor,$$ then 
    \begin{align}
        \label{eq:aux_prob_hat_t}
        \ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} \leq p'.
    \end{align}




    Let us fix $s \geq 0$ and $\widehat{t} \geq 0.$ Using the Chernoff method, we have
    \begin{align*}
        \Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq \widehat{t}} &= \Prob{-s \left(\sum_{i=1}^T \widehat{t}_{\eta_{i}}\right) \geq -s \widehat{t}} = \Prob{\exp\left(-s \sum_{i=1}^T \widehat{t}_{\eta_{i}}\right) \geq \exp\left(-s \widehat{t}\right)} \\
        &\leq e^{s \widehat{t}} \Exp{\exp\left(-s \sum_{i=1}^T \widehat{t}_{\eta_{i}}\right)}.
    \end{align*}
    Let us bound the expected value separately:
    \begin{align*}
        \Exp{\exp\left(-s \sum_{i=1}^T \widehat{t}_{\eta_{i}}\right)} = \Exp{\prod_{i = 1}^{T}\ExpCond{e^{-s \widehat{t}_{\eta_{i}}}}{\eta_{i-1}, \dots, \eta_{1}}}.
    \end{align*}
    Since $\widehat{t}_{\eta_{i}} \geq 0,$ we have
    \begin{align*}
        \ExpCond{e^{-s \widehat{t}_{\eta_{i}}}}{\eta_{i-1}, \dots, \eta_{1}} &= \ExpCond{e^{-s \widehat{t}_{\eta_{i}}}}{\widehat{t}_{\eta_{i}} \leq t', \eta_{i-1}, \dots, \eta_{1}} \ProbCond{\widehat{t}_{\eta_{i}} \leq t'}{\eta_{i-1}, \dots, \eta_{1}} \\
        &\quad + \ExpCond{e^{-s \widehat{t}_{\eta_{i}}}}{\widehat{t}_{\eta_{i}} > t', \eta_{i-1}, \dots, \eta_{1}} \left(1 - \ProbCond{\widehat{t}_{\eta_{i}} \leq t'}{\eta_{i-1}, \dots, \eta_{1}}\right) \\
        &\leq \ProbCond{\widehat{t}_{\eta_{i}} \leq t'}{\eta_{i-1}, \dots, \eta_{1}} + e^{-s t'} \left(1 - \ProbCond{\widehat{t}_{\eta_{i}} \leq t'}{\eta_{i-1}, \dots, \eta_{1}}\right) \\
        &\overset{\eqref{eq:aux_prob_hat_t}}{\leq} p' + e^{-s t'} \left(1 - p'\right).
    \end{align*}
    Thus
    \begin{align*}
        \Exp{\exp\left(-s \sum_{i=1}^T \widehat{t}_{\eta_{i}}\right)} \leq \left(p' + e^{-s t'} \left(1 - p'\right)\right)^T
    \end{align*}
    and
    \begin{align*}
        &\Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq \widehat{t}} \leq e^{s \widehat{t}} \left(p' + e^{-s t'} \left(1 - p'\right)\right)^T = e^{s \widehat{t} - s t' T} \left(1 + \left(e^{s t'} - 1\right)p'\right)^T.
    \end{align*}
    Let us take $s = \nicefrac{1}{t'},$ and get
    \begin{align}
        &\Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq \widehat{t}} \leq e^{\widehat{t} / t' - T} \left(1 + \left(e - 1\right)p'\right)^T \leq e^{\widehat{t} / t' - T + 2 p' T}.
        \label{eq:aux_prob}
    \end{align}
    Let us recall the definition of $p':$
    \begin{align*}
        p' = p \left(\sum_{i=1}^n \left\lfloor \frac{t'}{\tau_i}\right\rfloor\right)
    \end{align*}
    Now, we have to take the right $t'.$ We will take it using a nonconstructive definition. Assume that $t' = \frac{1}{4p}\left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right)^{-1},$ where $$j^* = \inf \left\{m \in [n] \,\middle|\, \frac{1}{4p}\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} < \tau_{m+1}\right\} \quad (\tau_{n + 1} \equiv \infty).$$
    This set is not empty because $n$ belongs to it. Using the definition of $j^*,$ we have
    \begin{align*}
        p' = p \left(\sum_{i=1}^n \left\lfloor \frac{t'}{\tau_i}\right\rfloor\right) = p \left(\sum_{i=1}^{j^*} \left\lfloor \frac{t'}{\tau_i}\right\rfloor\right) \leq p t' \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right) = \frac{1}{4}.
    \end{align*}
    Substituting this inequality to \eqref{eq:aux_prob}, we obtain
    \begin{align*}
        \Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq \widehat{t}} \leq e^{\widehat{t} / t' - \frac{T}{2}}.
    \end{align*}
    For $\widehat{t} \leq t' \left(\frac{T}{2} + \log \delta\right),$ we have
    \begin{align*}
        \Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq \widehat{t}} \leq \delta.
    \end{align*}
    Recall that $t' = \frac{1}{4p}\left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right)^{-1}.$ Using Lemma~\ref{lemma:tau}, we have $$t' \geq \frac{1}{24} \min_{m \in [n]} \left[\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + m\right)\right].$$

    Finally, we obtain
    \begin{align}
        \label{eq:aux_delta}
        \Prob{\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1} \leq \Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq  t} \leq \delta
    \end{align}
    for $$t \leq \frac{1}{24} \min_{m \in [n]} \left[\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + m\right)\right] \left(\frac{T}{2} + \log \delta\right).$$
\end{proof}




\subsubsection{Proof of Lemma~\ref{lemma:probs}}
\label{sec:lemma_probs}

In the following lemma, we use notations from Part 1 of the proof of Lemma~\ref{lemma:boundtime}.
\LEMMAPROBS*

In this lemma, we want to bound the probability for the random variable $\eta_{j+1}$ from \eqref{eq:geom_dist}. $\eta_{j+1}$ is the index of the first successful trial of the sequence of Bernouilli random variables. At first sight, this is a trivial task since $\eta_{j+1}$ has a distribution similar to the geometric distribution. But the main problem here is that the sequence $k^{\xi}_{j,i}$ and the quantity $m_{j+1}$ are also random variables. Therefore, we must be careful with this.

\begin{proof}
    Since the image of the random variables $\eta_{j}, \dots, \eta_{1}$ is in $\N \cap \{\infty\}.$ Let us take $l_1, \dots, l_{j} \in \N \cup \{\infty\},$ and prove the theorem for a probability conditioned on an event $\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}$ such that $\Prob{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} > 0.$ Therefore, it is enough to prove that
    \begin{align*}
        \ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq (1 - p)^{l_{j+1} - 1}p.
    \end{align*}

    First, assume that exists $i \in [j]$ such that $l_i = \infty.$ It means that, for all $k \geq 0,$ $\textnormal{prog}(x^k) < j,$ thus $$\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} = 0$$ for all $l_{j+1} \in \N.$ Let us explain this step. if exists $i \in [j]$ such that $l_i = \infty,$ then an algorithm never get a progress to $j$\textsuperscript{th} coordinate, thus $\eta_{j+1} = \inf \{i \,|\, \xi^{k^{\xi}_{j,i}} = 1 \textnormal{ and } i \in [1, m_{j+1}]\} = \infty$ a.s. because $m_{j+1} = 0$ and $k^{\xi}_{j,i}$ is an empty sequence.

    Assume that $l_i < \infty$ for all $i \in [j].$ By the definition of $\eta_{j+1},$ we have $m_{j+1} \geq l_{j+1}$ and $\xi^{k^{\xi}_{j,1}} = \dots = \xi^{k^{\xi}_{j, l_{j+1}-1}} = 0$ and $\xi^{k^{\xi}_{j, l_{j+1}}} = 1.$ Thus
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq \ProbCond{\bigcap_{i=1}^{l_{j+1} - 1} \{\xi^{k^{\xi}_{j,i}}=0\}, \xi^{k^{\xi}_{j, l_{j+1}}} = 1, m_{j+1} \geq l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    Since $k^{\xi}_{j,s} < k^{\xi}_{j,i}$ a.s. for all $s < i \in [m_{j+1}]$, using the law of total probability, we have
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \nonumber\\
        &\leq \sum_{k_1 < \dots < k_{l_{j+1}} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 1} \{\xi^{k^{\xi}_{j,i}}=0\}, \xi^{k^{\xi}_{j, l_{j+1}}} = 1, m_{j+1} \geq l_{j+1}, \bigcap_{i=1}^{l_{j+1}} \{k^{\xi}_{j,i} = k_i\}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &= \sum_{k_1 < \dots < k_{l_{j+1}} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 1} \{\xi^{k_{i}}=0\}, \xi^{k_{l_{j+1}}} = 1, m_{j+1} \geq l_{j+1}, \bigcap_{i=1}^{l_{j+1}} \{k^{\xi}_{j,i} = k_i\}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}},
    \end{align*}
    where $\sum_{k_1 < \dots < k_{l_{j+1}} = 1}^{\infty}$ is a sum over a set $\{(k_1, \dots, k_{l_{j+1}}) \in \N^{l_{j+1}} \,|\, \forall i < p \in [l_{j+1}] : k_i < k_p\}.$ 
    Next, if the event
    \begin{align*}
    \bigcap_{i=1}^{l_{j+1}} \{k^{\xi}_{j,i} = k_i\} \bigcap \{m_{j+1} \geq l_{j+1}\}
    \end{align*}
    holds, then an event $\bigcap_{i=1}^{l_{j+1}} A_{k_i}$
    holds, where \begin{align*}
        A_{k_i} \eqdef \{s^{k_i-1}_{{i^{k_i}}, q} = 1 \textnormal{ and } t^{k_i} \geq s^{k_i-1}_{{i^{k_i}}, t} + \tau_{i^{k_i}} \textnormal{ and } \textnormal{prog}(s^{k_i-1}_{{i^{k_i}}, x}) = j\}.
    \end{align*}
    At the same time, if $\bigcap_{i=1}^{l_{j+1}} A_{k_i}$ holds, then $\{m_{j+1} \geq l_{j+1}\}$ holds. Therefore, 
    \begin{align*}
        \bigcap_{i=1}^{l_{j+1}} \{k^{\xi}_{j,i} = k_i\} \bigcap \{m_{j+1} \geq l_{j+1}\} = \bigcap_{i=1}^{l_{j+1}} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right)
    \end{align*}
    and 
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \nonumber\\
        &\leq \sum_{k_1 < \dots < k_{l_{j+1}} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 1} \{\xi^{k_{i}}=0\}, \xi^{k_{l_{j+1}}} = 1, \bigcap_{i=1}^{l_{j+1}} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    Let us define $\sigma(\xi^1, \dots, \xi^{k_{l_{j+1}-1}})$ as a sigma-algebra generated by $\xi^1, \dots, \xi^{k_{l_{j+1}-1}}.$ Note that, for all $i \in [l_{j+1} - 1],$ the event $\{\xi^{k_{i}}=0\} \in \sigma(\xi^1, \dots, \xi^{k_{l_{j+1}-1}}).$ Also,
    for all $i \in [l_{j+1}],$ the event $\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i} \in \sigma(\xi^1, \dots, \xi^{k_{l_{j+1}-1}}).$ Finally, since $k^{\xi}_{i-1,l_i} < k^{\xi}_{j,l_{j+1}},$ the event $$A_{k_{l_{j+1}}} \bigcap \{k^{\xi}_{j,l_{j+1}} = k_{l_{j+1}}\} \bigcap \{\eta_{i} = l_{i}\} \subseteq \sigma(\xi^1, \dots, \xi^{k_{l_{j+1}-1}})$$ for all $i \in [j].$ Therefore, the event $\{\xi^{k_{l_{j+1}}} = 1\}$ is independent of the event $$\bigcap_{i=1}^{l_{j+1} - 1} \{\xi^{k_{i}}=0\} \bigcap_{i=1}^{l_{j+1}} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right) \bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\} \in \sigma(\xi^1, \dots, \xi^{k_{l_{j+1}-1}})$$ because $\xi^k$ are i.i.d. random variables. Using the independence and the equality $\Prob{\xi^{k_{l_{j+1}}} = 1} = p,$ we have
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \nonumber\\
        &\leq p\sum_{k_1 < \dots < k_{l_{j+1}} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 1} \{\xi^{k_{i}}=0\}, \bigcap_{i=1}^{l_{j+1}} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    Since the events $\{k^{\xi}_{j,l_{j+1}} = k_{l_{j+1}}\} \bigcap A_{k_{l_{j+1}}}$ do not intersect, we can use the additivity of the probability.
    If $l_{j+1} = 1,$ we get
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq p \ProbCond{\bigcup_{i = 1}^{\infty} \left(\{k^{\xi}_{j,l_{j+1}} = i\} \bigcap A_{i}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq p,
    \end{align*}
    and prove the lemma for $l_{j+1} = 1.$
    Otherwise, if $l_{j+1} > 1,$ we obtain
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \nonumber\\
        &\leq p\sum_{k_1 < \dots < k_{l_{j+1} - 1} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 1} \{\xi^{k_{i}}=0\}, \bigcap_{i=1}^{l_{j+1} - 1} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right), \right.\\
        &\qquad\qquad\qquad\qquad\qquad\left.\bigcup_{i = k_{l_{j+1} - 1} + 1}^{\infty} \left(\{k^{\xi}_{j,l_{j+1}} = i\} \bigcap A_{i}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    For any events $A$ and $B,$ we have $\Prob{A, B} \leq \Prob{A},$ thus 
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \nonumber\\
        &\leq p\sum_{k_1 < \dots < k_{l_{j+1} - 1} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 1} \{\xi^{k_{i}}=0\}, \bigcap_{i=1}^{l_{j+1} - 1} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    Let us continue for $l_{j+1} > 1$ and rewrite the last inequality: 
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \nonumber\\
        &\leq p\sum_{k_1 < \dots < k_{l_{j+1} - 1} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 2} \{\xi^{k_{i}}=0\}, \xi^{k_{l_{j+1} - 1}}=0, \bigcap_{i=1}^{l_{j+1} - 1} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    Note that, for all $i \in [l_{j+1} - 2],$ the event $\{\xi^{k_{i}}=0\} \in \sigma(\xi^1, \dots, \xi^{k_{l_{j+1}-2}}).$ Also,
    for all $i \in [l_{j+1} - 1],$ the event $\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i} \in \sigma(\xi^1, \dots, \xi^{k_{l_{j+1}-2}}).$ Finally, since $k^{\xi}_{i-1,l_i} < k^{\xi}_{j,l_{j+1} - 1},$ the event $$A_{k_{l_{j+1} - 1}} \bigcap \{k^{\xi}_{j,l_{j+1} - 1} = k_{l_{j+1} - 1}\} \bigcap \{\eta_{i} = l_{i}\} \subseteq \sigma(\xi^1, \dots, \xi^{k_{l_{j+1}-2}})$$ for all $i \in [j].$ Therefore, the event $\{\xi^{k_{l_{j+1} - 1}} = 0\}$ is independent of the event $$\bigcap_{i=1}^{l_{j+1} - 2} \{\xi^{k_{i}}=0\} \bigcap_{i=1}^{l_{j+1} - 1} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right) \bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}.$$Thus, we have
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \nonumber\\
        &\leq p (1 - p)\sum_{k_1 < \dots < k_{l_{j+1} - 1} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 2} \{\xi^{k_{i}}=0\}, \bigcap_{i=1}^{l_{j+1} - 1} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    Since the events $\{k^{\xi}_{j,l_{j+1} - 1} = k_{l_{j+1} - 1}\} \bigcap A_{k_{l_{j+1} - 1}}$ do not intersect, we use the additivity of the probability. If $l_{j+1} = 2,$ we get
    \begin{align*}
        \ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} &\leq p (1 - p)\ProbCond{\bigcup_{i = 1}^{\infty} \left(\{k^{\xi}_{j,l_{j+1} - 1} = i\} \bigcap A_i\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &\leq p(1 - p),
    \end{align*}
    and prove the lemma for $l_{j+1} = 2.$
    Otherwise, if $l_{j+1} > 2,$ we obtain
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \nonumber\\
        &\leq p (1 - p)\sum_{k_1 < \dots < k_{l_{j+1} - 2} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 2} \{\xi^{k_{i}}=0\}, \bigcap_{i=1}^{l_{j+1} - 2} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right), \right.\\
        &\qquad\qquad\qquad\qquad\qquad\qquad\qquad \left. \bigcup_{i = k_{l_{j+1} - 2} + 1}^{\infty} \left(\{k^{\xi}_{j,l_{j+1} - 1} = i\} \bigcap A_i\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &\leq p (1 - p)\sum_{k_1 < \dots < k_{l_{j+1} - 2} = 1}^{\infty} \ProbCond{\bigcap_{i=1}^{l_{j+1} - 2} \{\xi^{k_{i}}=0\}, \bigcap_{i=1}^{l_{j+1} - 2} \left(\{k^{\xi}_{j,i} = k_i\} \bigcap A_{k_i}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}},
    \end{align*}
    where we use $\Prob{A, B} \leq \Prob{A}$ for any events $A$ and $B$.
    Using mathematical induction, we can continue and get that
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq p (1 - p)^{l_{j+1} - 1}.
    \end{align*}
\end{proof}















\subsubsection{Lemma~\ref{lemma:tau}}

This is a technical lemma that we use in the proof of Lemma~\ref{lemma:boundtime}.

\begin{lemma}
    \label{lemma:tau}
    Let us consider a sorted sequence $0 < \tau_1 \leq \dots \leq \tau_n \leq \tau_{n + 1} = \infty$ and a constant $S \geq \frac{1}{4}.$ We define
    \begin{align*}
        t_1 \eqdef S \left(\sum_{i=1}^{j^*_1} \frac{1}{\tau_i}\right)^{-1},
    \end{align*}
    where
    \begin{align*}
        j^*_1 = \inf \left\{m \in [n] \,\middle|\, S\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} < \tau_{m+1}\right\},
    \end{align*}
    and
    \begin{align*}
        t_2 \eqdef \min_{j \in [n]} \left[\left(\sum_{i=1}^{j} \frac{1}{\tau_i}\right)^{-1} \left(S + j\right)\right].
    \end{align*}
    Then $$t_1 \leq t_2 \leq 6 t_1.$$
\end{lemma}

\begin{proof}
    Additionally, let us define 
    \begin{align*}
        j^*_2 = \argmin_{j \in [n]} \left[\left(\sum_{i=1}^{j} \frac{1}{\tau_i}\right)^{-1} \left(S + j\right)\right],
    \end{align*}
    where $j^*_2$ is the smallest index. For $j^*_2 = 1,$ we have
    \begin{align*}
        t_2 = \tau_1 \left(S + 1\right) > \tau_1.
    \end{align*}


    For $j^*_2 > 1$, we have
    \begin{align*}
        \left(\sum_{i=1}^{j^*_2} \frac{1}{\tau_i}\right)^{-1}\left(S + j^*_2\right) < \left(\sum_{i=1}^{j^*_2 - 1} \frac{1}{\tau_i}\right)^{-1}\left(S + j^*_2 - 1\right).
    \end{align*}
    From this inequality, we get
    \begin{align*}
        \left(\sum_{i=1}^{j^*_2 - 1} \frac{1}{\tau_i}\right)\left(S + j^*_2\right) < \left(\sum_{i=1}^{j^*_2} \frac{1}{\tau_i}\right)\left(S + j^*_2 - 1\right)
    \end{align*}
    and
    \begin{align*}
        \left(\sum_{i=1}^{j^*_2} \frac{1}{\tau_i}\right) < \frac{1}{\tau_{j^*_2}} \left(S + j^*_2\right).
    \end{align*}
    Thus $\tau_{j^*_2} < t_2$ for all $j^*_2 \geq 1.$

    Then either $j^*_2 \leq j^*_1$ and 
    \begin{align*}
        t_2 = \left(\sum_{i=1}^{j^*_2} \frac{1}{\tau_i}\right)^{-1} \left(S + j^*_2\right) \geq S \left(\sum_{i=1}^{j^*_2} \frac{1}{\tau_i}\right)^{-1} \geq S \left(\sum_{i=1}^{j^*_1} \frac{1}{\tau_i}\right)^{-1} = t_1,
    \end{align*}
    or $j^*_2 > j^*_1$ and 
    \begin{align*}
        t_2 > \tau_{j^*_2} \geq \tau_{j^*_1 + 1} > S \left(\sum_{i=1}^{j^*_1} \frac{1}{\tau_i}\right)^{-1} = t_1,
    \end{align*}
    where we used the definition of $j^*_1.$ It concludes that $t_2 \geq t_1.$ 

    Assume that $j_1^* > S + 1.$ Since the harmonic mean of a sequence less or equal to the maximum, we have
    \begin{align*}
        S \left(\sum_{i=1}^{j^*_1 - 1} \frac{1}{\tau_i}\right)^{-1} < \left(j^*_1 - 1\right) \left(\sum_{i=1}^{j^*_1 - 1} \frac{1}{\tau_i}\right)^{-1} \leq \tau_{j^*_1 - 1} \leq \tau_{j^*_1}.
    \end{align*}
    This inequality contradicts the definition of $j^*_1.$ It means that $j^*_1 \leq S + 1$ and
    \begin{align*}
        t_2 & \leq \left(\sum_{i=1}^{j^*_1} \frac{1}{\tau_i}\right)^{-1} \left(S + j^*_1\right) \leq \left(\sum_{i=1}^{j^*_1} \frac{1}{\tau_i}\right)^{-1} \left(2 S + 1\right) \leq \left(\sum_{i=1}^{j^*_1} \frac{1}{\tau_i}\right)^{-1} \left(6 S \right) \leq 6 t_1.
    \end{align*}
\end{proof}

\subsection{Proof of Theorems~\ref{thm:sgd_homog} and \ref{theorem:homog_time}}

\subsubsection{Proof of Theorems~\ref{thm:sgd_homog}}
\label{sec:proof_of_thm:sgd_homog}

\THEOREMSGDHOMOG*

\begin{proof}
    Note that Method~\ref{alg:alg_server} is just the stochastic gradient method with the batch size $S.$ Method~\ref{alg:alg_server} can be rewritten as $x^{k+1} = x^k - \gamma \frac{1}{S} \sum_{i=1}^S \widehat{\nabla} f(x^k;\xi_i),$ where the $\xi_i$ are independent random samples. It means that we can use the classical SGD result (see Theorem~\ref{theorem:sgd}). For a stepsize $$\gamma = \min\left\{\frac{1}{L}, \frac{\varepsilon S}{2 L \sigma^2}\right\},$$ we have
    \begin{align*}
        \frac{1}{K}\sum_{k=0}^{K-1}\Exp{\norm{\nabla f(x^k)}^2} \leq \varepsilon,
    \end{align*}
    if $$K \geq \frac{12 \Delta L}{\varepsilon} + \frac{12 \Delta L \sigma^2}{\varepsilon^2 S}.$$ Using the choice of $S,$ we showed that Method~\ref{alg:alg_server} converges after $$K \geq \frac{24 \Delta L}{\varepsilon}$$ steps with 
    $$\gamma = \min\left\{\frac{1}{L}, \frac{\varepsilon S}{2 L \sigma^2}\right\} \geq \frac{1}{2 L}.$$
\end{proof}

\subsubsection{The classical SGD theorem}
We reprove the classical SGD result \citep{ghadimi2013stochastic, khaled2020better}.
\begin{theorem}
    \label{theorem:sgd}
    Assume that Assumptions~\ref{ass:lipschitz_constant} and \ref{ass:lower_bound} hold. We consider the SGD method: $$x^{k+1} = x^k - \gamma g(x^k),$$ where
    \begin{align*}
        \gamma = \min\left\{\frac{1}{L}, \frac{\varepsilon}{2 L \sigma^2}\right\}
    \end{align*} 
    For a fixed $x \in \R^d$, $g(x)$ is a random vector such that $\Exp{g(x)} = \nabla f(x),$ \begin{align}
        \label{eq:aux_sigma}
        \Exp{\norm{g(x) - \nabla f(x)}^2} \leq \sigma^2,
    \end{align} and $g(x^k)$ are independent vectors for all $k \geq 0.$ Then
    \begin{align*}
        \frac{1}{K}\sum_{k=0}^{K-1}\Exp{\norm{\nabla f(x^k)}^2} \leq \varepsilon
    \end{align*}
    for
    \begin{align*}
        K \geq \frac{4 \Delta L}{\varepsilon} + \frac{8 \Delta L \sigma^2}{\varepsilon^2}.
    \end{align*}
\end{theorem}

\begin{proof}
    From Assumption~\ref{ass:lipschitz_constant}, we have
    \begin{align*}
        f(x^{k+1}) &\leq f(x^k) + \inp{\nabla f(x^k)}{x^{k+1} - x^{k}} + \frac{L}{2} \norm{x^{k+1} - x^{k}}^2 \\
        &= f(x^k) - \gamma \inp{\nabla f(x^k)}{g(x^k)} + \frac{L \gamma^2}{2} \norm{g(x^k)}^2.
    \end{align*}
    We denote $\mathcal{G}^k$ as a sigma-algebra generated by $g(x^0), \dots, g(x^{k-1}).$ Using unbiasedness and \eqref{eq:aux_sigma}, we obtain
    \begin{align*}
        \ExpCond{f(x^{k+1})}{\mathcal{G}^k} &\leq f(x^k) - \gamma \left(1 - \frac{L \gamma}{2}\right) \norm{\nabla f(x^k)}^2 + \frac{L \gamma^2}{2} \ExpCond{\norm{g^k - \nabla f(x^k)}^2}{\mathcal{G}^k} \\
        &\leq f(x^k) - \gamma \left(1 - \frac{L \gamma}{2}\right) \norm{\nabla f(x^k)}^2 + \frac{L \gamma^2 \sigma^2}{2}.
    \end{align*}
    Since $\gamma \leq \nicefrac{1}{L},$ we get
    \begin{align*}
        \ExpCond{f(x^{k+1})}{\mathcal{G}^k} \leq f(x^k) - \frac{\gamma}{2} \norm{\nabla f(x^k)}^2 + \frac{L \gamma^2 \sigma^2}{2}.
    \end{align*}
    We subtract $f^*$ and take the full expectation to obtain
    \begin{align*}
        \Exp{f(x^{k+1}) - f^*} \leq \Exp{f(x^k) - f^*} - \frac{\gamma}{2} \Exp{\norm{\nabla f(x^k)}^2} + \frac{L \gamma^2 \sigma^2}{2}.
    \end{align*}
    Next, we sum the inequality for $k \in \{0, \dots, K - 1\}$:
    \begin{align*}
        \Exp{f(x^{K}) - f^*} &\leq f(x^0) - f^* - \sum_{k=0}^{K-1}\frac{\gamma}{2} \Exp{\norm{\nabla f(x^k)}^2} + \frac{K L \gamma^2 \sigma^2}{2} \\
        & = \Delta - \sum_{k=0}^{K-1}\frac{\gamma}{2} \Exp{\norm{\nabla f(x^k)}^2} + \frac{K L \gamma^2 \sigma^2}{2}.
    \end{align*}
    Finally, we rearrange the terms and use that $\Exp{f(x^{K}) - f^*} \geq 0$:
    \begin{align*}
        \frac{1}{K}\sum_{k=0}^{K-1}\Exp{\norm{\nabla f(x^k)}^2} \leq \frac{2 \Delta}{\gamma K} + L \gamma \sigma^2.
    \end{align*}
    The choice of $\gamma$ and $K$ ensures that
    \begin{align*}
        \frac{1}{K}\sum_{k=0}^{K-1}\Exp{\norm{\nabla f(x^k)}^2} \leq \varepsilon.
    \end{align*}
\end{proof}

\subsubsection{Proof of Theorems~\ref{theorem:homog_time}}
\label{sec:proof_of_thm:homog_time}

\THEOREMSGDHOMOGTIME*

\begin{proof}
    In this setup, the method converges after $K \times$\emph{\{time required to collect a batch of the size $S$\}.}
    Without loss of generality, we assume that $\tau_1 \leq \dots \leq \tau_n.$ 

    Let us define time that is enough to collect a batch of the size $S$ as $t'.$ Obviously, one can always take $t' = 3 \tau_{n} \left\lceil\frac{S}{n}\right\rceil$ and guarantees that every worker calculates at least $\left\lceil\frac{S}{n}\right\rceil$ stochastic gradients, but we will provide a tighter $t'.$

    We define $B_i$ as the number of received gradients with an iteration index equals to $k.$\footnote{Note that a worker may send a gradient from the previous iterations that we ignore in the method.} 
    For each worker, there are two options: either the $i$\textsuperscript{th} worker does not send a gradient with an iteration index $k$ and $B_i = 0,$ or it sends at least once and $B_i > 0.$

    In the worst case, for $i$\textsuperscript{th} worker, the time required to calculate $B_i$ gradients equals
    \begin{align*}
        t_i \eqdef 
    \begin{cases}
        \tau_i \left(1 + B_i\right) & B_i > 0 \\
        0 & B_i = 0
    \end{cases} 
    \end{align*}
    because either $B_i > 0$ and, in the worst case, a worker finishes the calculation of a gradient from the previous iteration (that we ignore) and only then starts the calculation of a gradient of the current iteration $k,$ or $B_i = 0$ and the server does not receive any gradients from a worker.

    Note that all workers work in parallel, so our goal is to find feasible points $t' \in \R$ and $B_1, \cdots, B_n \in \N_0$ such that
    \begin{align}
        \label{eq:aux_t_problem}
        &t' \geq \max_{i \in [n]}t_i \nonumber\\
        &B_1, \cdots, B_n \in \N_0 \\
        &\sum_{i=1}^n {B_i} \geq S \nonumber
    \end{align}

    First, we relax an assumption that $B_i \in \N_0$ and assume that $B_i \in \R$ for all $i \in [n]:$ 
    \begin{align}
        \label{eq:aux_t_problem_relaxed}
        &t' \geq \max_{i \in [n]}t_i \nonumber\\
        &B_1, \cdots, B_n \in \R \\
        &B_1, \cdots, B_n \geq 0 \nonumber \\
        &\sum_{i=1}^n {B_i} \geq S \nonumber
    \end{align}
    If $B_i \in \R$ are feasible points of \eqref{eq:aux_t_problem_relaxed}, then 
    \begin{align*}&\max_{i \in [n]}t_i = \max_{B_i > 0} \tau_i \left(1 + B_i\right) \leq \max_{B_i > 0} \tau_i \left(1 + \lceil B_i \rceil\right) \\
        &\leq \max_{B_i > 0} \tau_i \left(2 + B_i \right) \leq 2 \max_{B_i > 0} \tau_i \left(1 + B_i \right) = 2 \max_{i \in [n]}t_i.
    \end{align*}
    It means that if $t' \in \R$ and $B_1, \cdots, B_n$ are feasible points of \eqref{eq:aux_t_problem_relaxed}, then $2 t'$ and $\lceil B_1 \rceil, \cdots, \lceil B_n \rceil$ are feasible points of \eqref{eq:aux_t_problem}.


    Let us define 
    \begin{align*}
        t'(j) \eqdef \left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1}\left(S + j\right) \quad \forall j \in [n],
    \end{align*}
    and take $j^* = \argmin_{j \in [n]} t'(j),$ $j^*$ is the smallest index from all minimizers of $t'(j).$ Let us show that 
    $t'(j^*)$ and 
    \begin{align*}
        B_i = \begin{cases}
            \frac{t'(j^*)}{\tau_i} - 1, & i \leq j^*\\
            0, & i > j^*
        \end{cases}
    \end{align*}
    are feasible points of \eqref{eq:aux_t_problem_relaxed}. First, we have
    \begin{align*}
        \sum_{i=1}^n B_i = \sum_{i=1}^{j^*} \left(\frac{t'(j^*)}{\tau_i} - 1\right) = \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right)^{-1}\left(S + j^*\right) \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right) - j^* = S.
    \end{align*}
    Next, we show that $B_i > 0$ for all $i \leq j^*.$ If $j^* = 1,$ then $t'(1) = \tau_1 (S + 1),$ thus $B_1 = S > 0.$ If $j^* > 1,$ then, by its definition, we have $t'(j^*) < t'(j^* - 1),$ thus
    \begin{align*}
        \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right)^{-1}\left(S + j^*\right) < \left(\sum_{i=1}^{j^* - 1} \frac{1}{\tau_i}\right)^{-1}\left(S + j^* - 1\right).
    \end{align*}
    From this inequality, we get
    \begin{align*}
        \left(\sum_{i=1}^{j^* - 1} \frac{1}{\tau_i}\right)\left(S + j^*\right) < \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right)\left(S + j^* - 1\right)
    \end{align*}
    and
    \begin{align*}
        \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right) < \frac{1}{\tau_{j^*}} \left(S + j^*\right).
    \end{align*}
    From the last inequality, we get that $\tau_{j^*} < t'(j^*),$ thus $B_{i} \geq B_{j^*} > 0$ for all $i \leq j^*.$ It is left to show that
    \begin{align*}
        \max_{i \in [n]} t_i = \max_{i \leq j^*} \tau_i \left(B_i + 1\right) = t'(j^*).
    \end{align*}

    Finally, we can conclude that Method~\ref{alg:alg_server} returns a solution after
    \begin{align*}
        K \times 2 t'(j^*) = \frac{48 \Delta L}{\varepsilon} \min_{j \in [n]} \left[\left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1}\left(S + j\right)\right]
    \end{align*}
    seconds.
\end{proof}

\section{Proofs for Heterogeneous Regime}

\subsection{Proof of Theorem~\ref{theorem:lower_bound_heterog}}
\THEOREMLOWERBOUNDHETROG*

The structure of the following proof is similar to the proof of Theorem~\ref{theorem:lower_bound_homog}. In the heterogeneous regime, the main difference is that we have more freedom to choose the functions $f_i.$

\begin{proof}
    In \eqref{eq:lower_bound_heterog}, we have the sum of two terms. We split the proof in two parts for each of the terms.\\
    (\textbf{Part 1}) \\
    (\textbf{Step 1}: $f \in \cF_{\Delta, L}$) \\
    Let us fix $\lambda > 0.$ We consider the following functions $f_i:$
    \begin{align*}
        f_i(x) \eqdef 
        \begin{cases} 
            0, & i < n, \\
            \frac{n L \lambda^2}{l_1} F_{T}\left(\frac{x}{\lambda}\right), & i = n.
        \end{cases}
    \end{align*}
    Let us show that the function $f$ is $L$-smooth:
    \begin{align*}
        \norm{\nabla f(x) - \nabla f(y)} &= \frac{1}{n}\norm{\sum_{i=1}^n \left(\nabla f_i(x) - \nabla f_i(y)\right)} = \frac{L \lambda}{l_1} \norm{\nabla F_{T}\left(\frac{x}{\lambda}\right) - \nabla F_{T}\left(\frac{y}{\lambda}\right)} \leq L \norm{x - y}.
    \end{align*}
    Let us take $$T = \left\lfloor\frac{\Delta l_1}{L \lambda^2 \Delta^0}\right\rfloor,$$ then
    \begin{align*}
        f(0) - \inf_{x \in \R^T} f(x) = \frac{1}{n} \frac{n L \lambda^2}{l_1} (F_{T}\left(0\right) - \inf_{x \in \R^{T}} F_{T}(x)) \leq \frac{L \lambda^2 \Delta^0 T}{l_1} \leq \Delta.
    \end{align*}
    We showed that the function $f \in \cF_{\Delta, L}.$\\
    (\textbf{Step 2}: Oracle Class)


    In the oracles $O_i,$ we have the freedom to choose a mapping $\widehat{\nabla} f_i(\cdot; \cdot)$ (see \eqref{eq:oracle_stochastic_delay}). In this part of the proof, we simply take non-stochastic mappings $\widehat{\nabla} f_i(x; \xi) \eqdef \nabla f_i(x)$ that are, obviously, unbiased and $\sigma^2$-variance-bounded. We can take an arbitrary distribution, for instance, let us take $\mathcal{D}_i = \textnormal{Bernouilli(1)}$ for all $i \in [n].$

    (\textbf{Step 3}: Analysis of Protocol)

    We take 
    $$\lambda = \frac{l_1 \sqrt{\varepsilon}}{L}$$
    to ensure that 
    \begin{align*}
        \norm{\nabla f(x)}^2 &= \frac{1}{n^2} \norm{\nabla f_n(x)}^2 = \frac{L^2 \lambda^2}{l_1^2} \norm{\nabla F_{T}\left(\frac{x}{\lambda}\right)}^2 > \frac{L^2 \lambda^2}{l_1^2} = \varepsilon
    \end{align*}
    for all $x \in \R^T$ such that $\textnormal{prog}(x) < T.$
    Thus
    $$T = \left\lfloor\frac{\Delta L}{l_1 \varepsilon \Delta^0}\right\rfloor.$$
    Only the $n$\textsuperscript{th} worker contains a nonzero function and can provide a gradient every $\tau_n$ seconds. Since $A$ is a zero-respecting algorithm and the function $f_n$ is a zero-chain function, for all $k \geq 0$ such that
    \begin{align*}
        t^k < \tau_n T,
    \end{align*}
    we have $$\norm{\nabla f(x^k)} > \varepsilon$$ because we need at least $T$ oracle calls to obtain $\textnormal{prog}(x^k) \geq T.$
    It means that
    \begin{align*}
        \inf_{k \in S_t} \norm{\nabla f(x^k)}^2 > \varepsilon
    \end{align*}
    for $$t = \tau_n \left(\frac{\Delta L}{l_1 \varepsilon \Delta^0} - 1\right).$$

    We now prove the second part of the lower bound.\\
    (\textbf{Part 2})\\
    (\textbf{Step 1}: $f \in \cF_{\Delta, L}$)

    Let us fix $\lambda > 0.$ We assume that $x = [x_1, \dots, x_n] \in \R^{nT}.$ We define $x_i \in \R^{T}$ as the $i$\textsuperscript{th} block of a vector $x = [x_1, \dots, x_n] \in \R^{nT}.$ We consider the following functions $f_i:$ 
    \begin{align*}
        f_i(x) \eqdef \frac{n L \lambda_i^2}{l_1} F_{T}\left(\frac{x_i}{\lambda_i}\right).
    \end{align*}
    The function $f_i$ depends only on a subset of variables $x_i$ from $x.$ Let us show that the function $f$ is $L$-smooth. Indeed, we have
    \begin{align*}
        \norm{\nabla f_i(x) - \nabla f_i(y)} = \frac{n L \lambda_i}{l_1} \norm{\nabla F_{T}\left(\frac{x_i}{\lambda_i}\right) - \nabla F_{T}\left(\frac{y_i}{\lambda_i}\right)} \leq n L \norm{x_i - y_i} \quad \forall i \in [n],
    \end{align*}
    and
    \begin{align*}
        \norm{\nabla f(x) - \nabla f(y)}^2 &= \frac{1}{n^2}\norm{\sum_{i=1}^n \left(\nabla f_i(x) - \nabla f_i(y)\right)}^2 = \frac{1}{n^2}\sum_{i=1}^n \norm{\nabla f_i(x) - \nabla f_i(y)}^2\\
        &\leq \frac{1}{n^2}\sum_{i=1}^n n^2 L^2 \norm{x_i - y_i}^2 = L^2\norm{x - y}^2.
    \end{align*}
    Let us take $$T = \left\lfloor \frac{\Delta l_1}{L \sum_{j=1}^n \lambda_j^2 \Delta^0} \right\rfloor \quad,$$ then
    \begin{align*}
        f(0) - \inf_{x \in \R^T} f(x) = \frac{1}{n} \sum_{i=1}^n \frac{n L \lambda_i^2}{l_1} (F_{T}\left(0\right) - \inf_{x \in \R^{T}} F_{T}(x)) \leq \sum_{i=1}^n \frac{L \lambda_i^2 \Delta^0 T}{l_1} \leq \Delta.
    \end{align*}
    We showed that the function $f \in \cF_{\Delta, L}.$

    (\textbf{Step 2}: Oracle Class)

    In the oracles $O_i,$ we have the freedom to choose a mapping $\widehat{\nabla} f_i(\cdot; \cdot)$ (see \eqref{eq:oracle_stochastic_delay}). Let us take 
    $$[\widehat{\nabla} f_i(x; \xi)]_j \eqdef \nabla_j f_i(x) \left(1 + \mathbbm{1}\left[j > (i - 1)T + \textnormal{prog}(x_i)\right]\left(\frac{\xi}{p_i} - 1\right)\right) \quad \forall x \in \R^{nT},$$ 
    $\mathcal{D}_i = \textnormal{Bernouilli}(p_i),$ and $p_i \in (0, 1]$ for all $i \in [n].$
Let us show it is unbiased and $\sigma^2$-variance-bounded:
 $$\Exp{[\widehat{\nabla} f_i(x; \xi)]_j} = \nabla_j f_i(x) \left(1 + \mathbbm{1}\left[j > (i - 1)T + \textnormal{prog}(x_i)\right]\left(\frac{\Exp{\xi}}{p_i} - 1\right)\right) = \nabla_j f_i(x)$$ for all $j \in nT,$ and
\begin{align*}
    \Exp{\norm{\widehat{\nabla} f_i(x; \xi) - \nabla f_i(x)}^2} \leq \norm{\nabla f_i(x)}_{\infty}^2\Exp{\left(\frac{\Exp{\xi}}{p_i} - 1\right)^2}
\end{align*}
because the difference is non-zero only in one coordinate.
Thus
\begin{align*}
    \Exp{\norm{\widehat{\nabla} f_i(x; \xi) - \nabla f_i(x)}^2} &\leq \frac{\norm{\nabla f_i(x)}_{\infty}^2(1 - p_i)}{p_i} = \frac{n^2 L^2 \lambda_i^2 \norm{F_{T}\left(\frac{x_i}{\lambda_i}\right)}_{\infty}^2(1 - p_i)}{l_1^2 p_i} \\
    &\leq \frac{n^2 L^2 \lambda_i^2 \gamma_{\infty}^2 (1 - p_i)}{l_1^2 p_i} \leq \sigma^2,
\end{align*}
where we take 
$$p_i = \min\left\{\frac{n^2 L^2 \lambda_i^2 \gamma_{\infty}^2}{\sigma^2 l_1^2}, 1\right\}.$$

(\textbf{Step 3}: Analysis of Protocol)

We fix $\eta > 0$ and choose 
$$\lambda_i = \frac{l_1 \sqrt{\eta \varepsilon \tau_i}}{L \sqrt{\sum_{i=1}^n \tau_i}}$$
to ensure that 
\begin{align}
    \norm{\nabla f(x)}^2 &= \frac{1}{n^2} \sum_{i=1}^n \norm{\nabla f_i(x)}^2 = \sum_{i=1}^n \frac{L^2 \lambda_i^2}{l_1^2}\norm{\nabla F_{T_i} \left(\frac{x_i}{\lambda_i}\right)}^2 \nonumber \\ 
    &= \sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i}\norm{\nabla F_{T_i} \left(\frac{x_i}{\lambda_i}\right)}^2 > \sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i}\mathbbm{1}[\textnormal{prog} (x_i) < T]
    \label{eq:aux_step_3_bound}
\end{align}
for all $x = [x_1, \dots, x_n] \in \R^{T}.$
Thus
$$T = \left\lfloor\frac{\Delta L}{\eta \varepsilon l_1 \Delta^0}\right\rfloor$$
and
\begin{align}
    \label{eq:prob_choice}
    p_i = \min\left\{\frac{n^2 \gamma_{\infty}^2 \eta \varepsilon \tau_i}{\sigma^2 \sum_{i=1}^n \tau_i}, 1\right\} \quad \forall i \in [n].
\end{align}


Protocol~\ref{alg:time_multiple_oracle_protocol} generates the sequence $\{x^k\}_{k=0}^{\infty} \equiv \{[x^k_1, \dots, x^k_n]\}_{k=0}^{\infty}.$ From \eqref{eq:aux_step_3_bound}, we have
\begin{align}
    \label{eq:aux_f_lower}
    \inf_{k \in S_t} \norm{\nabla f(x^k)}^2 > \inf_{k \in S_t} \sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i}\mathbbm{1}[\textnormal{prog} (x_i^k) < T] \geq \sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i}\inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T].
\end{align}
Further, we require the following auxillary lemma. See the proof in Section~\ref{sec:lemma_boundtime_heterog}.
\begin{restatable}{lemma}{LEMMABOUNDTIMEHETROG}
    \label{lemma:boundtime_heterog}
    For $\eta = 4,$ with probability not less than $1 / 2,$
    \begin{align*}
        \sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i}\inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] > 2 \varepsilon
    \end{align*}
    for $$t \leq \frac{1}{24} \left(\frac{\sigma^2 \sum_{i=1}^n \tau_i}{n^2 \gamma_{\infty}^2 \eta \varepsilon}\right) \left(\frac{T}{2} - 1\right).$$
\end{restatable}

Using Lemma~\ref{lemma:boundtime_heterog} and \eqref{eq:aux_f_lower}, we have
\begin{align*}
    \Exp{\inf_{k \in S_t} \norm{\nabla f(x^k)}^2} > \varepsilon
\end{align*}
for $$t = \frac{1}{24} \left(\frac{\sigma^2 \sum_{i=1}^n \tau_i}{4 n^2 \gamma_{\infty}^2 \varepsilon}\right) \left(\frac{\Delta L}{8 \varepsilon l_1 \Delta^0} - 2\right).$$
This finishes the proof of Part 2.




























\end{proof}

\subsection{Proof of Lemma~\ref{lemma:boundtime_heterog}}
\label{sec:lemma_boundtime_heterog}

In the following lemma, we use notations from the proof of Theorem~\ref{theorem:lower_bound_heterog}.

\LEMMABOUNDTIMEHETROG*

\begin{proof}
    Let us fix $t \geq 0.$ Our goal is to show that the probability of an inequality \begin{align}
        \label{eq:aux_sum_eps}
        \sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i}\inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] \leq 2 \varepsilon
    \end{align} is small. 

    We now use the same reasoning as in Lemma~\ref{lemma:boundtime}. We use a notation $\left\{x\right\}_i$ is $i$\textsuperscript{th} block of the vector $x$.
    Let us fix a worker's index $i \in [n].$ 

    \begin{definition}[Sequence $k^{\xi}_{i,j,l}$]
        Let us consider a set
        \begin{align*}
            \left\{k \in \N \,|\, s^{k-1}_{{i^k}, q} = 1 \textnormal{, } t^{k} \geq s^{k-1}_{{i^k}, t} + \tau_{i^k} \textnormal{, } \textnormal{prog}\left(\left\{s^{k-1}_{{i^k}, x}\right\}_i\right) = j, i^k = i\right\}, \quad s^{k-1}_{{i^{k}}} \equiv (s^{k-1}_{{i^{k}}, t}, s^{k-1}_{{i^{k}}, q}, s^{k-1}_{{i^{k}}, x}).
        \end{align*}
        We order this set and define the result sequence as $\{k^{\xi}_{i,j,l}\}_{i=1}^{m_{i,j+1}},$ where $m_{i,j+1} \in [0, \infty]$ is the size of the sequence. The sequence $k^{\xi}_{i,j,l}$ is a subsequence of iterations where the $i$\textsuperscript{th} oracle use the generated Bernouilli random variables in \eqref{eq:oracle_stochastic_delay} when $\textnormal{prog}\left(\left\{s_{x}\right\}_i\right) = j.$ The sequence $s^{k-1}_{{i^{k}}}$ is defined in Protocol~\ref{alg:time_multiple_oracle_protocol}.
    \end{definition}

    Then $$\eta_{i,j+1} \eqdef \inf \{l \,|\, \xi^{k^{\xi}_{i,j,l}} = 1 \textnormal{ and } l \in [1, m_{i,j+1}]\} \in \N \cup \{\infty\}.$$
    The quantity $\eta_{i,j+1}$ is the index of the first successful trial, when $\textnormal{prog}(\cdot) = j$ in the $i$\textsuperscript{th} block of the sequence $x^k$. Since the algorithm $A$ is a zero-respecting algorithm, for all $k < k^{\xi}_{i,j,\eta_{i,j+1}},$ the progress $\textnormal{prog}(x^k_i) < j + 1.$ 

    As in Lemma~\ref{lemma:boundtime} (we skip the proof since the idea is the same. It is only required to use the different notations: $x^k \rightarrow x^k_i, \widehat{t}_{\eta_{j}} \rightarrow \widehat{t}_{i,\eta_{i,j}}$), for all $i \in [n],$ one can show that if $\inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] < 1$ holds, then $\sum_{j=1}^{T} \widehat{t}_{i,\eta_{i,j}} \leq t,$ where $\widehat{t}_{i,k} \eqdef k\tau_i$ for all $k \geq 1.$ The time $\widehat{t}_{i,k}$ is the smallest possible time when the $i$\textsuperscript{th} oracle can return the $k$\textsuperscript{th} stochastic gradient. Thus
    \begin{align*}
        \Prob{\sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i}\inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] \leq 2 \varepsilon} \leq \Prob{\sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i} \mathbbm{1}\left[\sum_{j=1}^{T} \widehat{t}_{i,\eta_{i,j}} \leq t\right] \leq 2 \varepsilon}.
    \end{align*}
    Using \eqref{eq:aux_delta} with $n = 1$ (and the different notations $p \rightarrow p_i, \tau_1 \rightarrow \tau_i,$ and $\widehat{t}_{\eta_{j}} \rightarrow \widehat{t}_{i,\eta_{i,j}}$), we have
    \begin{align}\
        \label{eq:aux_large_prob}
        \Prob{\sum_{j=1}^{T} \widehat{t}_{i,\eta_{i,j}} \leq t} \leq \delta \quad \forall t \leq \frac{\tau_i}{24 p_i} \left(\frac{T}{2} + \log \delta\right).
    \end{align}
    We now rearrange the terms and use Markov's inequality to obtain
    \begin{align*}
        &\Prob{\sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i} \mathbbm{1}\left[\sum_{j=1}^{T} \widehat{t}_{i,\eta_{i,j}} > t\right] \leq 2 \varepsilon} \\
        &= \Prob{\sum_{i=1}^n \tau_i \mathbbm{1}\left[\sum_{j=1}^{T} \widehat{t}_{i,\eta_{i,j}} \leq t\right] \geq \left(1 - \frac{2}{\eta}\right) \sum_{i=1}^n \tau_i} \\
        &\leq \left(1 - \frac{2}{\eta}\right)^{-1} \left(\sum_{i=1}^n \tau_i\right)^{-1}\Exp{\sum_{i=1}^n \tau_i \mathbbm{1}\left[\sum_{j=1}^{T} \widehat{t}_{i,\eta_{i,j}} \leq t\right]} \\
        &= \left(1 - \frac{2}{\eta}\right)^{-1} \left(\sum_{i=1}^n \tau_i\right)^{-1} \sum_{i=1}^n \tau_i \Prob{\sum_{j=1}^{T} \widehat{t}_{i,\eta_{i,j}} \leq t},
    \end{align*}
    for $\eta > 2.$
    Using the choice of $p_i$ in \eqref{eq:prob_choice}, we have $$\frac{\tau_i}{p_i} \geq \frac{\sigma^2 \sum_{i=1}^n \tau_i}{n^2 \gamma_{\infty}^2 \eta \varepsilon}$$ for all $i \in [n].$
    The last term does not depend on $i.$ Therefore, we can use \eqref{eq:aux_large_prob} with $$t \leq \frac{1}{24} \left(\frac{\sigma^2 \sum_{i=1}^n \tau_i}{n^2 \gamma_{\infty}^2 \eta \varepsilon}\right) \left(\frac{T}{2} + \log \delta\right)$$ to get
    \begin{align*}
        \Prob{\sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i} \mathbbm{1}\left[\sum_{j=1}^{T} \widehat{t}_{i,\eta_{i,j}} > t\right] \leq 2 \varepsilon}
        \leq \left(1 - \frac{2}{\eta}\right)^{-1} \left(\sum_{i=1}^n \tau_i\right)^{-1} \left(\sum_{i=1}^n \tau_i\right) \delta = \left(1 - \frac{2}{\eta}\right)^{-1} \delta.
    \end{align*}
    Finally, for $\eta = 4$ and $\delta = 1 / 4,$ we have
    \begin{align*}
        \Prob{\sum_{i=1}^n \frac{\eta \varepsilon \tau_i}{\sum_{i=1}^n \tau_i}\inf_{k \in S_t} \mathbbm{1}[\textnormal{prog} (x_i^k) < T] \leq 2 \varepsilon} \leq \frac{1}{2}.
    \end{align*}


\end{proof}





\subsection{Proof of Theorem~\ref{thm:sgd_heterog}}

\THEOREMSGDHETROG*

\begin{proof}
    Note that Method~\ref{alg:alg_server_heterog} can be rewritten as $x^{k+1} = x^k - \gamma \frac{1}{n} \sum_{i=1}^n \frac{1}{B_i} \sum_{j=1}^{B_i} \widehat{\nabla} f_i(x^k;\xi_{i,j}),$ where the $\xi_{i,j}$ are independent random samples. The variance of the gradient estimator equals
    \begin{align*}
        &\Exp{\norm{\frac{1}{n} \sum_{i=1}^n \frac{1}{B_i} \sum_{j=1}^{B_i} \widehat{\nabla} f_i(x^k;\xi_{i,j}) - \nabla f(x^k)}^2}\\
        &=\frac{1}{n^2} \sum_{i=1}^n \Exp{\norm{\frac{1}{B_i} \sum_{j=1}^{B_i} \widehat{\nabla} f_i(x^k;\xi_{i,j}) - \nabla f_i(x^k)}^2} \\
        &=\frac{1}{n^2} \sum_{i=1}^n \frac{1}{B_i^2} \sum_{j=1}^{B_i} \Exp{\norm{\widehat{\nabla} f_i(x^k;\xi_{i,j}) - \nabla f_i(x^k)}^2} \leq \frac{1}{n^2} \sum_{i=1}^n \frac{\sigma^2}{B_i} = \left(\frac{1}{n} \sum_{i=1}^n \frac{1}{B_i}\right) \frac{\sigma^2}{n} \leq \frac{\sigma^2}{S},
    \end{align*}
    where we use the inequality $\left(\frac{1}{n} \sum_{i=1}^n \frac{1}{B_i}\right)^{-1} \geq \frac{S}{n},$
    We can use the classical SGD result (see Theorem~\ref{theorem:sgd}). For a stepsize $$\gamma = \min\left\{\frac{1}{L}, \frac{\varepsilon S}{2 L \sigma^2}\right\},$$ we have
    \begin{align*}
        \frac{1}{K}\sum_{k=0}^{K-1}\Exp{\norm{\nabla f(x^k)}^2} \leq \varepsilon,
    \end{align*}
    if $$K \geq \frac{12 \Delta L}{\varepsilon} + \frac{12 \Delta L \sigma^2}{\varepsilon^2 S}.$$ Using the choice of $S,$ we obtain that Method~\ref{alg:alg_server_heterog} converges after $$K \geq \frac{24 \Delta L}{\varepsilon}$$ steps.
\end{proof}

\subsection{Proof of Theorem~\ref{theorem:heterog_time}}

\THEOREMSGDHETROGTIME*

\begin{proof}
    The method converges after $K \times$\emph{\{time required to collect batches with the sizes $B_i$ such that $\left(\frac{1}{n} \sum_{i=1}^n \nicefrac{1}{B_i}\right)^{-1} \geq \frac{S}{n}$ holds\}.}

    In the worst case, for $i$\textsuperscript{th} worker, the time required to calculate $B_i$ gradients equals
    \begin{align*}
        t_i \eqdef \tau_i \left(1 + B_i\right)
    \end{align*}
    because it is possible that a worker finishes the calculation of a gradient from the previous iteration (that we ignore) and only then starts the calculation of a gradient of the current iteration.

    Our goal is to find feasible points $t' \in \R$ and $B_1, \cdots, B_n \in \N$ such that
    \begin{align}
        \label{eq:aux_t_problem_het}
        &t' \geq \max_{i \in [n]}t_i, \nonumber\\
        &B_1, \cdots, B_n \in \N, \\
        &\left(\frac{1}{n} \sum_{i=1}^n \frac{1}{B_i}\right)^{-1} \geq \frac{S}{n}. \nonumber
    \end{align}
    Using the same reasoning as in Theorem~\ref{theorem:homog_time}, we relax the assumption that $B_i \in \N$ and assume that $B_i \in \R$ for all $i \in [n]:$ 
    \begin{align}
        \label{eq:aux_t_problem_relaxed_het}
        &t' \geq \max_{i \in [n]}t_i \nonumber\\
        &B_1, \cdots, B_n \in \R \\
        &B_1, \cdots, B_n > 0\nonumber \\
        &\left(\frac{1}{n} \sum_{i=1}^n \frac{1}{B_i}\right)^{-1} \geq \frac{S}{n}, \nonumber
    \end{align}
If $t' \in \R$ and $B_1, \cdots, B_n$ are feasible points of \eqref{eq:aux_t_problem_relaxed_het}, then $2 t'$ and $\lceil B_1 \rceil, \cdots, \lceil B_n \rceil$ are feasible points of \eqref{eq:aux_t_problem_het}. Let us show that $t' = 2 \left(\tau_{n} + \left(\frac{1}{n} \sum_{i=1}^n \tau_i\right) \frac{S}{n}\right)$ and $B_i = \frac{t'}{\tau_i} - 1$ are feasible points. Indeed, for all $i \in [n],$
\begin{align*}
    B_i = \frac{t'}{\tau_i} - 1 \geq \frac{2 \tau_n}{\tau_i} - 1 \geq 1.
\end{align*}
Next, we have
\begin{align*}
    \max_{i \in [n]} t_i = \max_{i \in [n]} \tau_i \left(B_i + 1\right) = t'
\end{align*}
and
\begin{align*}
    \left(\frac{1}{n} \sum_{i=1}^n \frac{1}{B_i}\right)^{-1} = \left(\frac{1}{n} \sum_{i=1}^n \frac{\tau_i}{t' - \tau_i}\right)^{-1} \geq \left(\frac{1}{n} \sum_{i=1}^n \frac{2 \tau_i}{t'}\right)^{-1} = \frac{t'}{2} \left(\frac{1}{n} \sum_{i=1}^n \tau_i\right)^{-1} \geq \frac{S}{n},
\end{align*}
where we use $t' - \tau_i \geq t' / 2 + \tau_i - \tau_i = t' / 2$ for all $i \in [n].$
Finally, it means that Method~\ref{alg:alg_server_heterog} returns a solution after
    \begin{align*}
        K \times 2 t' = \frac{96 \Delta L}{\varepsilon} \left(\tau_{n} + \left(\frac{1}{n} \sum_{i=1}^n \tau_i\right) \frac{S}{n}\right)
    \end{align*}
seconds.
\end{proof}

\section{Interrupt Oracle Calculations}
\label{sec:stop_oracle}
Let us define a protocol and an oracle where an algorithm can stop the oracle anytime. If an algorithm stops the oracle, its current calculations are canceled and discarded.
\begin{protocol}[H]
    \caption{Time Multiple Oracles Protocol With Control}
    \label{alg:time_multiple_oracle_protocol_with_control}
    \begin{algorithmic}[1]
    \STATE \textbf{Input: }functions $f \in \cF,$ oracles and distributions $((O_1, \dots, O_n), (\mathcal{D}_1, \dots, \mathcal{D}_n)) \in \cO(f),$ algorithm $A \in \cA$
    \STATE $s^0_i = 0$ for all $i \in [n]$
    \FOR{$k = 0, \dots, \infty$}
\STATE $(t^{k+1}, i^{k+1}, {\orange c^{k}}, x^k) = A^k(g^1, \dots, g^{k}), \hfill $$\rhd\,{t^{k+1} \geq t^{k}} \hspace{1.82cm}$
    \STATE $(s^{k+1}_{{i^{k+1}}}, g^{k+1}) = O_{{i^{k+1}}}({t^{k+1}}, x^k, {\orange c^{k}}, s^{k}_{{i^{k+1}}}, \xi^{k+1}), \quad \xi^{k+1} \sim \mathcal{D}$ \hfill $\rhd\,s^{k+1}_j = s^{k}_j \quad \forall j \neq i^{k+1}$
    \ENDFOR
    \end{algorithmic}
\end{protocol}


In Protocol~\ref{alg:time_multiple_oracle_protocol_with_control}, we allow algorithms to output the control variables $c^{k}$ that can be used in the following oracle.

We take an oracle $$O_{\tau}^{\smallnablafunc}\,:\, \R_{\geq 0} \times \R^d \times \underbrace{(\R_{\geq 0} \times \R^d \times \{0, 1\})}_{\textnormal{input state}} \times \underbrace{\{0, 1\}}_{\textnormal{control}} \times \mathbb{S}_{\xi} \rightarrow \underbrace{(\R_{\geq 0} \times \R^d \times \{0, 1\})}_{\textnormal{output state}} \times \R^d$$ such that
\begin{align}
    \label{eq:oracle_stochastic_delay_control}
    O_{\tau}^{\smallnablafunc}(t, x, (s_t, s_x, s_q), c, \xi) = 
\left\{
\begin{aligned}
    &((t, x, 1), &0), \qquad & c = 0 \textnormal{ and } s_q = 0, \\
    &((s_t, s_x, 1), &0), \qquad & c = 0 \textnormal{ and } s_q = 1 \textnormal{ and } t < s_t + \tau,\\
    &((0, 0, 0), & \widehat{\nabla} f(s_x; \xi)), \qquad & c = 0 \textnormal{ and } s_q = 1 \textnormal{ and } t \geq s_t + \tau, \\
    &((0, 0, 0), & 0), \qquad & c = 1,
\end{aligned}
\right.
\end{align}
and $\widehat{\nabla} f$ is a mapping such that
\begin{align*}
    \widehat{\nabla} f\,:\, \R^d \times \mathbb{S}_\xi \rightarrow \R^d.
\end{align*}
The oracle \eqref{eq:oracle_stochastic_delay_control} generalizes the oracle \eqref{eq:oracle_stochastic_delay} since an algorithm can send a signal $c$ to the oracle \eqref{eq:oracle_stochastic_delay_control} and interrupt the calculations. Note that if $c = 1,$ then \eqref{eq:oracle_stochastic_delay_control} has the same behavior as \eqref{eq:oracle_stochastic_delay}. But, if $c = 0,$ then the oracle \eqref{eq:oracle_stochastic_delay_control} discards all previous information in the state, and changes $s_q$ to $0.$ 

Let us define an oracle class:
\begin{definition}[Oracle Class $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{stop}}$]\ \\
    Let us consider an oracle class such that, for any $f \in \cF_{\Delta, L},$ it returns oracles $O_i = O_{\tau_i}^{\smallnablafunc}$ and distributions $\mathcal{D}_i$ for all $i \in [n],$ where $\widehat{\nabla} f$ is an unbiased $\sigma^2$-variance-bounded mapping (see Assumption~\ref{ass:stochastic_variance_bounded}). The oracles $O_{\tau_i}^{\smallnablafunc}$ are defined in \eqref{eq:oracle_stochastic_delay_control}. We define such oracle class as $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{stop}}.$ Without loss of generality, we assume that $0 < \tau_1 \leq \dots \leq \tau_n.$ \label{def:oracle_class_control}
\end{definition}

For the oracle class $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{stop}}$, we state that 
\begin{align*}
    \mathfrak{m}_{\textnormal{time}}\left(\cA_{\textnormal{zr}}, \cF_{\Delta, L}\right) = \Omega\left(\min_{m \in [n]} \left[\left(\frac{1}{m} \sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right]\right).
\end{align*}
The lower bound is the same as for the oracle class from Definition~\ref{def:oracle_class}. We do not provide a formal proof, but a close investigation can reveal that the proof is the same as in Theorem~\ref{theorem:lower_bound_homog}. 

Indeed, in Part 1 of the proof of Lemma~\ref{lemma:boundtime}, we reduce the the inequality $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ to the inequality $\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq t$, where $\widehat{t}_{\eta_{i}}$ is the shortest time when the oracles can draw a successful Bernouilli random variable. The fact that an algorithm can interrupt the oracles can not change the quantity $\widehat{t}_{\eta_{i}}.$

\section{Time Complexity with Synchronized Start}
\label{sec:sync_start}
In this section, we continue and fill up the discussion in Section~\ref{sec:sync_start_main}.

Let us design an oracle for the synchronized start setting. We take an oracle $$O_{\tau_1, \dots, \tau_n}^{\smallnablafunc}\,:\, \R_{\geq 0} \times \R^d \times \underbrace{(\R_{\geq 0} \times \R^d \times \{0, 1\})}_{\textnormal{input state}} \times \underbrace{(\mathbb{S}_{\xi} \times \dots \times \mathbb{S}_{\xi})}_{n \textnormal{ times}} \rightarrow \underbrace{(\R_{\geq 0} \times \R^d \times \{0, 1\})}_{\textnormal{output state}} \times \R^d$$ such that

\begin{align}
    \label{eq:oracle_stochastic_delay_sync}
    &O_{\tau_1, \dots, \tau_n}^{\smallnablafunc}(t, x, (s_t, s_x, s_q), (\xi_1, \dots, \xi_n)) = \nonumber\\
&\left\{
\begin{aligned}
    &((t, x, 1), &0), \qquad & s_q = 0, \\
    &((0, 0, 0), &0), \qquad & s_q = 1 \textnormal{ and } t \in [0, s_t + \tau_1),\\
    &((0, 0, 0), & \widehat{\nabla} f(s_x; \xi_1)), \qquad & s_q = 1 \textnormal{ and } t \in [s_t + \tau_1, s_t + \tau_2),\\
    &((0, 0, 0), & \sum_{i=1}^2 \widehat{\nabla} f(s_x; \xi_i)), \qquad & s_q = 1 \textnormal{ and } t \in [s_t + \tau_2, s_t + \tau_3),\\
    &\dots\\
    &((0, 0, 0), & \sum_{i=1}^n \widehat{\nabla} f(s_x; \xi_i)), \qquad & s_q = 1 \textnormal{ and } t \in [s_t + \tau_n, \infty),\\
\end{aligned}
\right.
\end{align}
and $\widehat{\nabla} f$ is a mapping such that
\begin{align*}
    \widehat{\nabla} f\,:\, \R^d \times \mathbb{S}_\xi \rightarrow \R^d.
\end{align*}
We assume that $\xi^{k+1}$ is a tuple in Protocol~\ref{alg:time_oracle_protocol}: $\xi^{k+1} \equiv (\xi_1^{k+1}, \dots, \xi_n^{k+1}) \sim \mathcal{D}.$

The oracle \eqref{eq:oracle_stochastic_delay_sync} with Protocol~\ref{alg:time_oracle_protocol} emulates the behavior of a setting where we broadcast an iterate $x$ to all workers, and they start calculations simultaneously. The workers have different time delays, hence some finish earlier than others. An algorithm can stop the procedure earlier and get calculated stochastic gradients, but other non-calculated ones will be discarded.

For this oracle, we define an oracle class:
\begin{definition}[Oracle Class $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{sync}}$]\ \\
    \label{def:oracle_sync}
    Let us consider an oracle class such that, for any $f \in \cF_{\Delta, L},$ it return an oracle $O = \cO_{\tau_1, \dots, \tau_n}^{\smallnablafunc}$ and a distribution $\mathcal{D},$ where $\widehat{\nabla} f$ is an unbiased $\sigma^2$-variance-bounded mapping (see Assumption~\ref{ass:stochastic_variance_bounded}). The oracle $O_{\tau_1, \dots, \tau_n}^{\smallnablafunc}$ is defined in \eqref{eq:oracle_stochastic_delay_sync}. We define such oracle class as $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{sync}}.$ Without loss of generality, we assume that $0 < \tau_1 \leq \dots \leq \tau_n.$ \label{def:oracle_class_sync}
\end{definition}

We now provide the lower bound for Protocol~\ref{alg:time_oracle_protocol} and the oracle class $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{sync}}.$

\begin{restatable}{theorem}{THEOREMLOWERBOUNDSYNC}
    \label{theorem:lower_bound_homog_sync}
    Let us consider the oracle class $\cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{sync}}$ for some $\sigma^2 >0$ and $0 < \tau_1 \leq \dots \leq \tau_n.$ We fix any $L, \Delta > 0$ and $0 < \varepsilon \leq c' L \Delta.$ In the view Protocol~\ref{alg:time_oracle_protocol}, for any algorithm $A \in \cA_{\textnormal{zr}},$ there exists a function $f \in \cF_{\Delta, L}$ and an oracle and a distribution $(O, \mathcal{D}) \in \cO_{\tau_1, \dots, \tau_n}^{\sigma^2, \textnormal{sync}}(f)$
    such that $\Exp{\inf_{k \in S_t} \norm{\nabla f(x^k)}^2} > \varepsilon,$
    where $S_t \eqdef \left\{k \in \N_0 \middle| t^{k} \leq t\right\},$ and $$t = c \times \min_{m \in [n]} \left[\tau_m \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right].$$ The quantity $c'$ and $c$ are {\markchanges universal} constants.
\end{restatable}

\subsection{Minimax optimal method}
In this section, we analyze the $m$--Minibatch SGD method (see Method~\ref{alg:alg_server_m_star}). This method generalizes the Minibatch SGD method from Section~\ref{sec:previous_parallel_algorithms}. Unlike Minibatch SGD, the $m$--Minibatch SGD method only asks for stochastic gradients from the first $m \in [n]$ (fastest) workers. Later, we show that optimal $m$ is determined by \eqref{eq:optimal_m}. And with this parameter, $m$--Minibatch SGD method is minimax optimal under the setting from Sections \ref{sec:sync_start_main} and \ref{sec:sync_start}. Note that $m$--Minibatch SGD is Minibatch SGD if $m = n.$


\begin{method}
    \caption{$m$--Minibatch SGD}
    \label{alg:alg_server_m_star}
    \begin{algorithmic}[1]
    \STATE \textbf{Input:} starting point $x^0$, stepsize $\gamma$, number of workers $m \in [n]$
    \FOR{$k = 0, 1, \dots, K - 1$}
    \STATE Send the point $x^k$ to the first $m$ workers
    \STATE Receive i.i.d. stochastic gradients $\widehat{\nabla} f(x^k, \xi_1), \dots, \widehat{\nabla} f(x^k, \xi_{m})$ from the workers
    \STATE $x^{k+1} = x^k - \gamma \frac{1}{m}\sum_{i=1}^{m} \widehat{\nabla} f(x^k, \xi_i)$
    \ENDFOR
    \end{algorithmic}
\end{method}

We now provide the convergence rate and the time complexity.

\begin{restatable}{theorem}{THEOREMSGDHOMOGSYNC}
    \label{thm:sgd_homog_sync}
    Assume that Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound} and \ref{ass:stochastic_variance_bounded} hold. 
    Let us take the step size $$\gamma = \min\left\{\frac{1}{L}, \frac{\varepsilon m}{2 L \sigma^2}\right\}$$ in Method~\ref{alg:alg_server_m_star},
    then after 
    \begin{eqnarray*}
        K \geq \frac{12 \Delta L}{\varepsilon} + \frac{12 \Delta L \sigma^2}{\varepsilon^2 m}
    \end{eqnarray*}
    iterations the method guarantees that $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\norm{\nabla f(x^k)}^2} \leq \varepsilon.$
\end{restatable}

\begin{restatable}{theorem}{THEOREMSGDHOMOGTIMESYNC}
\label{theorem:homog_time_sync}
Let us consider Theorem~\ref{thm:sgd_homog_sync}. We assume that $i$\textsuperscript{th} worker returns a stochastic gradient every $\tau_i$ seconds for all $i \in [n]$. Without loss of generality, we assume that $0 < \tau_1 \leq \cdots \leq \tau_n.$ Let us take
\begin{align}
    \label{eq:optimal_m}
    m = \argmin_{m' \in [n]} \tau_{m'}\left(1 + \frac{\sigma^2}{m' \varepsilon}\right).
\end{align}
Then after
\begin{align}
    \label{eq:homog_optim_complex_sync}
    12 \min_{m \in [n]} \tau_m \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)
\end{align}
seconds Method~\ref{alg:alg_server_m_star} guarantees to find an $\varepsilon$-stationary point.
\end{restatable}

Despite the triviality of the $m$--Minibatch SGD and it analysis, we provide it to show that the lower bound in Theorem~\ref{theorem:lower_bound_homog_sync} is tight.

\subsection{Proof of Theorem~\ref{theorem:lower_bound_homog_sync}}
\THEOREMLOWERBOUNDSYNC*

Step 1 and Step 2 mirrors the corresponding steps from the proof of Theorem~\ref{theorem:lower_bound_homog_sync}.
\begin{proof}
    (\textbf{Step 1}: $f \in \cF_{\Delta, L}$) \\
    Let us fix $\lambda > 0.$ We take the same function $f \in \cF_{\Delta, L}$ as in the proof of Theorem~\ref{theorem:lower_bound_homog}. We define $$f(x) \eqdef \frac{L \lambda^2}{l_1} F_T\left(\frac{x}{\lambda}\right)$$ with 
    $$T = \left\lfloor\frac{\Delta l_1}{L \lambda^2 \Delta^0}\right\rfloor.$$
    (\textbf{Step 2}: Oracle Class) \\
    Following the proof of Theorem~\ref{theorem:lower_bound_homog}, in the oracle $O,$ we take the following stochastic estimator
    \begin{align}\label{eq:stoch_grad_sync}[\widehat{\nabla} f(x; \xi)]_j \eqdef \nabla_j f(x) \left(1 + \mathbbm{1}\left[j > \textnormal{prog}(x)\right]\left(\frac{\xi}{p} - 1\right)\right) \quad \forall x \in \R^T,\end{align}
    and $\mathcal{D} = \underbrace{(\textnormal{Bernouilli}(p), \dots, \textnormal{Bernouilli}(p))}_{n \textnormal{ times}},$ where $p \in (0, 1].$ The stochastic gradient is unbiased and $\sigma^2$-variance-bounded if
    $$p = \min\left\{\frac{L^2 \lambda^2 \gamma_{\infty}^2}{\sigma^2 l_1^2}, 1\right\}.$$\\
    (\textbf{Step 3}: Analysis of Protocol)

We choose 
$$\lambda = \frac{\sqrt{2 \varepsilon} l_1}{L}$$
to ensure that $\norm{\nabla f(x)}^2 = \frac{L^2 \lambda^2}{l_1^2}\norm{\nabla F_T (\frac{x}{\lambda})}^2 > 2 \varepsilon \mathbbm{1}\left[\textnormal{prog}(x) < T\right]$ for all $x \in \R^T,$ where we use Lemma~\ref{lemma:worst_function}. Thus
$$T = \left\lfloor\frac{\Delta L}{2 \varepsilon l_1 \Delta^0}\right\rfloor$$
and
$$p = \min\left\{\frac{2 \varepsilon \gamma_{\infty}^2}{\sigma^2}, 1\right\}.$$

Protocol~\ref{alg:time_oracle_protocol} generates a sequence $\{x^k\}_{k=0}^{\infty}.$ We have
\begin{align}
    \label{eq:aux_part_3_homog_sync}
    \inf_{k \in S_t} \norm{\nabla f(x^k)}^2 > 2 \varepsilon \inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right].
\end{align}

Further, we require the following auxillary lemma. See the proof in Section~\ref{sec:aux_lemmas}.
\begin{restatable}{lemma}{LEMMABOUNDTIMESYNC}
    \label{lemma:boundtime_sync}
    With probability not less than $1 - \delta,$
    \begin{align*}
        \inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] \geq 1
    \end{align*}
    for $$t \leq \frac{1}{2} \min_{m \in [n]} \tau_{m}\left(1 + \frac{1}{4 p m}\right) \left(\frac{T}{2} + \log \delta\right).$$
\end{restatable}

Using Lemma~\ref{lemma:boundtime_sync} with $\delta = 1/2$ and \eqref{eq:aux_part_3_homog_sync}, we obtain
\begin{align*}
    \Exp{\inf_{k \in S_t} \norm{\nabla f(x^k)}^2} &\geq 2 \varepsilon \Prob{\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right]} > \varepsilon
\end{align*}
for $$t = \frac{1}{2} \min_{m \in [n]} \tau_{m}\left(1 + \frac{\sigma^2}{8 \gamma_{\infty}^2 m \varepsilon}\right) \left(\frac{\Delta L}{2 \varepsilon l_1 \Delta^0} - 2\right).$$
\end{proof}

\subsubsection{Proof of Lemma~\ref{lemma:boundtime_sync}}
\LEMMABOUNDTIMESYNC*

\begin{proof}
    \textbf{(Part 1):} \emph{Comment: in this part, we mirror the proof of Lemma~\ref{lemma:boundtime}. We also show that if $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, then we have the inequality $\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq t$, where $\widehat{t}_{\eta_{i}}$ are random variables with some known ``good'' distributions. However, in this lemma the quantities $\widehat{t}_{\eta_{i}}$ are different.}\\
    In Protocol~\ref{alg:time_oracle_protocol}, the algorithm $A$ consequently calls the oracle $O.$ If $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, then exists $k \in S_t$ such that $\textnormal{prog}(x^{k}) = T.$ Since the algorithm $A$ is zero-respecting, the mappings $A^k$ will not output a non-zero vector (a vector with a non-zero first coordinate) unless the oracle returns a non-zero vector. 

    Let us define the smallest index $k(i)$ of the sequence when the progress $\textnormal{prog}(x^{k(i)})$ equals $i:$
    \begin{align*}
        k(i) \eqdef \inf\left\{k \in \N_0\,|\, i = \textnormal{prog} (x^k)\right\} \in \N_0 \cup \{\infty\}.
    \end{align*}


    \begin{definition}[Sequence $(k^{\xi}_p, i^{\xi}_p)$]
    Let us consider a set
    \begin{align*}
        \{(k, i) \in \N \times [n] \,|\, s^{k-1}_{q} = 1 \textnormal{ and } t^{k} \geq s^{k-1}_{t} + \tau_{i}\}, \quad s^{k-1} \equiv (s^{k-1}_{t}, s^{k-1}_{q}, s^{k-1}_{x}).
    \end{align*}
    We order this set lexicographically and define the result sequence as $\{(k^{\xi}_p, i^{\xi}_p)\}_{p=1}^m,$ where $m \in [0, \infty]$ is the size of the sequence. 
    The sequence $s^{k-1}$ is defined in Protocol~\ref{alg:time_oracle_protocol}.
    \end{definition}

    Note that the algorithm $A$ is only depends on the random samples $\left\{\xi^{k^{\xi}_p}_{i^{\xi}_p}\right\}_{p=1}^{m}$ since the sequence $\{(k^{\xi}_p, i^{\xi}_p)\}_{p=1}^m$ are the indices of the random samples that are used in the oracle \eqref{eq:oracle_stochastic_delay_sync}.

    Let us denote the index of the first successful trial as $\eta_1,$ i.e., 
    $$\eta_1 \eqdef \inf \left\{i \,\middle|\, \xi^{k^{\xi}_p}_{i^{\xi}_p} = 1 \textnormal{ and } p \in [1, m]\right\} \in \N \cup \{\infty\}.$$


    If $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, 
    then $\eta_1 < \infty.$
    Using the times $t^k,$ the algorithm $A$ consequently requests the gradient estimators from the oracle \eqref{eq:oracle_stochastic_delay_sync}. 

    In each round of the oracle's calculation, the algorithm can get the vector $\widehat{\nabla} f(s_x; \xi_1)$ in not less than $\tau_1$ seconds, the vector $\sum_{i=1}^2 \widehat{\nabla} f(s_x; \xi_i)$ in less than $\tau_2$ seconds, and so forth (see \eqref{eq:oracle_stochastic_delay_sync}). The algorithm can repeat any number of these rounds sequentially.

    The algorithm $A$ one by one requests $m_1, \dots, m_i, \dots \in \{0, \dots, n\}$ gradient estimators from the oracle \eqref{eq:oracle_stochastic_delay_sync}. It takes at least $\tau_{m_i}$ seconds  ($\tau_0 \equiv 0$) to get a vector $\sum_{i=1}^{m_i} \widehat{\nabla} f(s_x; \xi_i)$. Let us consider that $k \in \N$ is the \emph{first} index of gradient estimators such that is depends on some $\xi_i = 1.$ Necessarily, we have $\sum_{j=1}^k m_j \geq \eta_1.$ Also, since the $A$ is zero-respecting, we have $\sum_{j=1}^k \tau_{m_j} \leq t^{k(1)}.$ Note that $k,$ and $m_1, \dots, m_k.$ depend on the algorithm's strategy. Let us find ``the best possible'' quantities $k,$ and $m_1, \dots, m_k$ that are independent of an algorithm.

    Let us assume that $k^*,$ and $m_1^*, \dots m_k^*$ minimize the quantity 
    \begin{equation}
    \label{eq:aux_opt}
    \begin{aligned}
    & \min_{k, m_1, \dots, m_k}\sum_{j=1}^k \tau_{m_j},\\
    \textrm{s.t.} \quad & k \in \N,\\
        &m_1, \dots m_k \in \{0, \dots, n\},\\
        &\sum_{j=1}^k m_j \geq \eta_1.
    \end{aligned}
    \end{equation}
    Then, we have $$t^{k(1)} \geq \sum_{j=1}^{k^*} \tau_{m_j^*}.$$
    Note that if exists $j \in [k^*]$ such that $m_j^* > \eta_1,$ then $k^*,$ and $m_1^*, \dots, m_{j-1}^*, \eta_1, m_{j+1}^*\dots,  m_k^*$ are also minimizers of \eqref{eq:aux_opt} since the sequence $\tau_{k}$ is not decreasing. Therefore, \eqref{eq:aux_opt} is equivalent to 
    \begin{equation}
    \label{eq:aux_opt_2}
    \begin{aligned}
    & \min_{k, m_1, \dots, m_k} \sum_{j=1}^k \tau_{m_j},\\
    \textrm{s.t.} \quad & k \in \N,\\
        &m_1, \dots m_k \in \{0, \dots, \eta_1\},\\
        &\sum_{j=1}^k m_j \geq \eta_1.
    \end{aligned}
    \end{equation}
    Then, using the simple algebra, we have
    \begin{align*}
        t^{k(1)} &\geq \sum_{j=1}^{k^*} \tau_{m_j^*} = \sum_{j\,:\, m_j^* \neq 0} \tau_{m_j^*} = \sum_{j\,:\, m_j^* \neq 0} m_j^* \frac{\tau_{m_j^*}}{m_j^*} \geq \sum_{j\,:\, m_j^* \neq 0} m_j^* \min_{m \in [\eta_1]}\frac{\tau_{m}}{m} \\
        &=\sum_{j=1}^{k^*} m_j^* \min_{m \in [\eta_1]}\frac{\tau_{m}}{m} \geq \eta_1 \min_{m \in [\eta_1]}\frac{\tau_{m}}{m}.
    \end{align*}
    In the first inequality, we use that $m_j^* \in \{0, \dots, \eta_1\}$ for all $j \in [k^*].$ Next, using Lemma~\ref{lemma:tau_sync}, we get
    \begin{align*}
        t^{k(1)} &\geq \frac{1}{2} \min_{m \in [n]} \tau_{m}\left(1 + \frac{\eta_1}{m}\right).
    \end{align*}


    Using the same reasoning, for $j \in \{0, \dots, T-1\}$, $$t^{k(j+1)} \geq t^{k(j)} + \frac{1}{2} \min_{m \in [n]} \tau_{m}\left(1 + \frac{\eta_{j+1}}{m}\right),$$ where $\eta_{j+1}$ is the index of the first successful trial of Bernouilli random variables when $\textnormal{prog}(\cdot) = j.$ More formally, for all $j \in \{0, \dots, T - 1\}$:

    \begin{definition}[Sequence $(k^{\xi}_{j,p}, i^{\xi}_{j,p})$]
    Let us consider a set
    \begin{align*}
        \{(k, i) \in \N \times [n] \,|\, s^{k-1}_{q} = 1 \textnormal{ and } t^{k} \geq s^{k-1}_{t} + \tau_{i} \textnormal{ and } \textnormal{prog}(s^{k-1}_x) = j\}, \quad s^{k-1} \equiv (s^{k-1}_{t}, s^{k-1}_{q}, s^{k-1}_{x}).
    \end{align*}
    We order this set lexicographically and define the result sequence as $\{(k^{\xi}_{j,p}, i^{\xi}_{j,p})\}_{p=1}^{m_{j+1}},$ where $m_{j+1} \in [0, \infty]$ is the size of the sequence. 
    The sequence $s^{k-1}$ is defined in Protocol~\ref{alg:time_oracle_protocol}.
    \end{definition}

    Then, $$\eta_{j+1} \eqdef \inf \left\{i \,\middle|\, \xi^{k^{\xi}_{j,p}}_{i^{\xi}_{j,p}} = 1 \textnormal{ and } p \in [1, m_{j+1}]\right\} \in \N \cup \{\infty\}.$$
    By the definition of $k(j),$ $x^{k(j)}$ is the first iterate such that $\textnormal{prog}(\cdot) = j.$ Therefore, the oracle can potentially start returning gradient estimators with the non-zero $j+1$\textsuperscript{th} coordinate from the $k(j)$\textsuperscript{th} iteration.

    Thus, if $\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1$ holds, then
    \begin{align*}
        \frac{1}{2} \sum_{i=1}^T \min_{m \in [n]} \tau_{m}\left(1 + \frac{\eta_{i}}{m}\right) \leq t^{k(T)} \leq t.
    \end{align*}
    Finally, we can conclude that
    \begin{align}
        \label{eq:aux_bound_aux}
        \Prob{\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1} \leq \Prob{\frac{1}{2} \sum_{i=1}^T \min_{m \in [n]} \tau_{m}\left(1 + \frac{\eta_{i}}{m}\right) \leq t} \quad \forall t \geq 0.
    \end{align}
    As in Lemma~\ref{lemma:probs}, we show that
    \begin{restatable}{lemma}{LEMMAPROBSSYNC}
        \label{lemma:probs_sync}
        Let us take $l_{j+1} \in \N.$ Then
        \begin{align}
            \label{eq:aux_prob_eta}
            \ProbCond{\eta_{j+1} = l_{j+1}}{\eta_{j}, \dots, \eta_{1}} \leq (1 - p)^{l_{j+1} - 1}p
        \end{align}
        for all $j \in \{0, \dots, T-1\}.$
    \end{restatable}
    See the proof in Section~\ref{sec:lemma_probs_sync}. Intuitively, the algorithm $A$ can not increase the probability of getting a successful Bernouilli random variable earlier with its decisions.

    Let us temporally define $$\widehat{t}_{\eta_i} \eqdef \frac{1}{2} \min_{m \in [n]} \tau_{m}\left(1 + \frac{\eta_{i}}{m}\right)$$ for all $i \in [T].$ \\
    \textbf{(Part 2):} \emph{Comment: in this part, we use the standard technique to bound the large deviations of the sum $\sum_{i=1}^T \widehat{t}_{\eta_{i}}$.}\\
    Note that a function $g\,:\,\R \rightarrow \R$ such that $g(x) \eqdef \frac{1}{2} \min_{m \in [n]} \tau_{m}\left(1 + \frac{x}{m}\right)$ is continuous, strongly-monotone and invertible.
    For $t' \geq 0,$ we have 
    \begin{align*}
        &\ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} =\ProbCond{g(\eta_{j+1}) \leq t'}{\eta_{j}, \dots, \eta_{1}} = \ProbCond{\eta_{j+1} \leq g^{-1}(t')}{\eta_{j}, \dots, \eta_{1}}.
    \end{align*}
    Using \eqref{eq:aux_prob_eta}, we obtain
    \begin{align*}
        \ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} \leq \sum_{j=1}^{\left\lfloor g^{-1}(t')\right\rfloor} (1 - p)^{j - 1} p \leq p \left\lfloor g^{-1}(t')\right\rfloor.
    \end{align*}
    Let us define $$p' \eqdef p \left\lfloor g^{-1}(t')\right\rfloor,$$ then 
    \begin{align*}
        \ProbCond{\widehat{t}_{\eta_{j+1}} \leq t'}{\eta_{j}, \dots, \eta_{1}} \leq p'.
    \end{align*}
    Using the Chernoff method, as in Lemma~\ref{lemma:boundtime}, one can get
    \begin{align*}
        \Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq \widehat{t}} \leq e^{\widehat{t} / t' - T + 2 p' T}.
    \end{align*}
    Let us take
    \begin{align*}
        t' = g\left(\frac{1}{4p}\right) = \frac{1}{2} \min_{m \in [n]} \tau_{m}\left(1 + \frac{1}{4 p m}\right),
    \end{align*}
    then
    $$p' = p \left\lfloor g^{-1}\left(g\left(\frac{1}{4p}\right)\right)\right\rfloor = p \left\lfloor\frac{1}{4p}\right\rfloor \leq \frac{1}{4}.$$ Therefore,
    \begin{align*}
        \Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq \widehat{t}} \leq e^{\widehat{t} / t' - \frac{T}{2}}.
    \end{align*}
    Using \eqref{eq:aux_bound_aux}, for $$t \leq \frac{1}{2} \min_{m \in [n]} \tau_{m}\left(1 + \frac{1}{4 p m}\right) \left(\frac{T}{2} + \log \delta\right),$$ we have
    \begin{align*}
        \Prob{\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] < 1} \leq \Prob{\sum_{i=1}^T \widehat{t}_{\eta_{i}} \leq t} \leq \delta.
    \end{align*}
    The last inequality concludes the proof.


\end{proof}

\subsubsection{Lemma~\ref{lemma:tau_sync}}

\begin{lemma}
    \label{lemma:tau_sync}
    Let us consider a sorted sequence $0 < \tau_1 \leq \dots \leq \tau_n$ and a constant $\eta \in \N.$ We define
    \begin{align*}
        t_1 \eqdef \eta \min_{m \in [\eta]}\frac{\tau_{m}}{m},
    \end{align*}
    and
    \begin{align*}
        t_2 \eqdef \min_{m \in [n]} \tau_{m}\left(1 + \frac{\eta}{m}\right).
    \end{align*}
    Then $$t_1 \leq t_2 \leq 2 t_1.$$
\end{lemma}

\begin{proof}
    Additionally, let us define
    \begin{align*}
        m_1 \eqdef \argmin_{m \in [\eta]}\frac{\tau_{m}}{m}
    \end{align*}
    and
    \begin{align*}
        m_2 \eqdef \argmin_{m \in [n]} \tau_{m}\left(1 + \frac{\eta}{m}\right).
    \end{align*}
    Then, using $m_1 \leq \eta,$ we have
    \begin{align*}
        t_2 = \min_{m \in [n]} \tau_{m}\left(1 + \frac{\eta}{m}\right) \leq \tau_{m_1}\left(1 + \frac{\eta}{m_1}\right) \leq 2 \tau_{m_1}\frac{\eta}{m_1} = 2 t_1.
    \end{align*}
    If $m_2 \leq \eta,$ then
    \begin{align*}
        t_1 = \eta \min_{m \in [\eta]}\frac{\tau_{m}}{m} \leq \eta \frac{\tau_{m_2}}{m_2} \leq \tau_{m_2}\left(1 + \frac{\eta}{m_2}\right) = t_2.
    \end{align*}
    Otherwise, if $m_2 > \eta,$
    \begin{align*}
        t_1 = \eta \min_{m \in [\eta]}\frac{\tau_{m}}{m} \leq \eta \frac{\tau_{\eta}}{\eta} = \tau_{\eta} \leq \tau_{m_2} \leq \tau_{m_2}\left(1 + \frac{\eta}{m_2}\right) = t_2.
    \end{align*}
\end{proof}

\subsubsection{Proof of Lemma~\ref{lemma:probs_sync}}
\label{sec:lemma_probs_sync}

In the following lemma, we use notations from Part 1 of the proof of Lemma~\ref{lemma:boundtime_sync}.



\LEMMAPROBSSYNC*


The idea of the following proof repeats the proof of Lemma~\ref{lemma:probs_sync}. But Protocol~\ref{alg:time_oracle_protocol} with the oracle \eqref{eq:oracle_stochastic_delay_sync} differ, so we present the proof for completeness.

\begin{proof}
    We prove that
    \begin{align*}
        \ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq (1 - p)^{l_{j+1} - 1}p.
    \end{align*}
    for all $l_1, \dots, l_{j} \in \N \cup \{\infty\}$ such that $\Prob{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} > 0.$

    If exists $i \in [j]$ such that $l_i = \infty,$ then $$\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} = 0$$ for all $l_{j+1} \in \N$ (see details in the proof of Lemma~\ref{lemma:probs}).

    Assume that $l_i < \infty$ for all $i \in [j].$ By the definition of $\eta_{j+1},$ we have $m_{j+1} \geq l_{j+1}$ and $\xi^{k^{\xi}_{j,1}}_{i^{\xi}_{j,1}} = \dots = \xi^{k^{\xi}_{j,l_{j+1} - 1}}_{i^{\xi}_{j,l_{j+1} - 1}} = 0$ and $\xi^{k^{\xi}_{j,l_{j+1}}}_{i^{\xi}_{j,l_{j+1}}} = 1.$ Thus
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq \ProbCond{\bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k^{\xi}_{j,p}}_{i^{\xi}_{j,p}}=0\}, \xi^{k^{\xi}_{j,l_{j+1}}}_{i^{\xi}_{j,l_{j+1}}} = 1, m_{j+1} \geq l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    Let us define a set 
    $$S_{l_{j+1}} \eqdef \{((k_1, i_1), \dots, (k_{l_{j+1}}, i_{l_{j+1}})) \in (\N \times [n])^{l_{j+1}} \,|\, \forall p < j \in [l_{j+1}] : (k_p, i_p) < (k_j, i_j)\} \quad \forall l_{j+1} \geq 1.$$
    Using the law of total probability, we have
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &\leq \sum_{S_{l_{j+1}}} \ProbCond{\bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k^{\xi}_{j,p}}_{i^{\xi}_{j,p}}=0\}, \xi^{k^{\xi}_{j,l_{j+1}}}_{i^{\xi}_{j,l_{j+1}}} = 1, m_{j+1} \geq l_{j+1}, \bigcap_{p=1}^{l_{j+1}} \{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &= \sum_{S_{l_{j+1}}} \ProbCond{\bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k_p}_{i_p}=0\}, \xi^{k_{l_{j+1}}}_{i_{l_{j+1}}} = 1, m_{j+1} \geq l_{j+1}, \bigcap_{p=1}^{l_{j+1}} \{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    where we take the sum over all $((k_1, i_1), \dots, (k_{l_{j+1}}, i_{l_{j+1}})) \in S_{l_{j+1}}.$
    If the event 
    \begin{align*}
        \bigcap_{p=1}^{l_{j+1}} \{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap \{m_{j+1} \geq l_{j+1}\} 
    \end{align*}
    holds, then an event $\bigcap_{p=1}^{l_{j+1}} A_{(k_p, i_p)}$
    holds, where \begin{align*}
        A_{(k_p, i_p)} \eqdef \{s^{k_p-1}_{q} = 1 \textnormal{ and } t^{k_p} \geq s^{k_p-1}_{t} + \tau_{i_p} \textnormal{ and } \textnormal{prog}(s^{k_p-1}_x) = j\}.
    \end{align*}
    At the same time, if $\bigcap_{p=1}^{l_{j+1}} A_{(k_p, i_p)}$ holds, then $\{m_{j+1} \geq l_{j+1}\}$ holds. Therefore, 
    \begin{align*}
        \bigcap_{p=1}^{l_{j+1}} \{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap \{m_{j+1} \geq l_{j+1}\} = \bigcap_{p=1}^{l_{j+1}} \left(\{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap A_{(k_p, i_p)}\right)
    \end{align*}
    and 
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &\leq \sum_{S_{l_{j+1}}} \ProbCond{\bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k_p}_{i_p}=0\}, \xi^{k_{l_{j+1}}}_{i_{l_{j+1}}} = 1, \bigcap_{p=1}^{l_{j+1}} \left(\{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap A_{(k_p, i_p)}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    Let us define $\sigma^i_j$ as a sigma-algebra generated by $(\xi^1_1, \dots, \xi^1_n), (\xi^2_1, \dots, \xi^2_n), \dots, (\xi^{i}_1, \dots, \xi^{i}_j)$ for all $i \geq 0$ and $j \in \{0, \dots, n\}.$ Then, we have
    \begin{align*}
        \bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k_p}_{i_p}=0\} \in \sigma^{k_{l_{j+1} - 1}}_{i_{l_{j+1} - 1}},
    \end{align*}
    and
    \begin{align*}
        \bigcap_{p=1}^{l_{j+1}} \left(\{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap A_{(k_p, i_p)}\right) \in \sigma^{k_{l_{j+1}} - 1}_{n}
    \end{align*}
    since, for all $p \in [l_{j+1}],$ the event $A_{(k_p, i_p)}$ is only determined by $s^{k_p-1}$ and $t^{k_p}$ that \emph{do not} depend on $\{\xi^{j}\}_{j = k_{l_{j+1}}}^{\infty}.$ And, for all $p \in [l_{j+1}],$ the fact that $(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)$ \emph{does not} depend on $\{\xi^{j}\}_{j = k_{l_{j+1}}}^{\infty}.$ Note that $k^{\xi}_{i-1,l_{i}} < k^{\xi}_{j,l_{j+1}}$ (a.s.) for all $i \in [j].$ Thus
    \begin{align*}
        A_{(k_{l_{j+1}}, i_{l_{j+1}})} \bigcap \{(k^{\xi}_{j,l_{j+1}}, i^{\xi}_{j,l_{j+1}}) = (k_{l_{j+1}}, i_{l_{j+1}})\} \bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\} \in \sigma^{k_{l_{j+1}} - 1}_{n}
    \end{align*}
    since, for all $i \in [j],$ this event implies that $k^{\xi}_{i-1,l_{i}} < k_{l_{j+1}}.$ All in all, we have that
    \begin{align*}
        \bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k_p}_{i_p}=0\} \bigcap_{p=1}^{l_{j+1}} \left(\{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap A_{(k_p, i_p)}\right)\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\} \in \sigma^{k_{l_{j+1}} - 1}_{n} \bigcup \sigma^{k_{l_{j+1} - 1}}_{i_{l_{j+1} - 1}}.
    \end{align*}
    Since $\{\xi^{k_{l_{j+1}}}_{i_{l_{j+1}}} = 1\}$ is independent of $\sigma^{k_{l_{j+1}} - 1}_{n} \bigcup \sigma^{k_{l_{j+1} - 1}}_{i_{l_{j+1} - 1}},$\footnote{For all $i, j \geq 0$ and $l, p \in \{0, \dots, n\}, $ the union of $\sigma^i_l$ and $\sigma^j_p$ is a sigma-algebra since either $\sigma^i_l \subseteq \sigma^j_p,$ or $\sigma^j_p \subseteq \sigma^i_l.$} we get
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &\leq p \sum_{S_{l_{j+1}}} \ProbCond{\bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k_p}_{i_p}=0\}, \bigcap_{p=1}^{l_{j+1}} \left(\{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap A_{(k_p, i_p)}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}}.
    \end{align*}
    If $l_{j+1} = 1,$ observe that the events $\{(k^{\xi}_{j,l_{j+1}}, i^{\xi}_{j,l_{j+1}}) = (k_{l_{j+1}}, i_{l_{j+1}})\} \bigcap A_{(k_{l_{j+1}}, i_{l_{j+1}})}$ do not intersect for all $(k_{l_{j+1}}, i_{l_{j+1}}) \in \N \times [n].$ Thus, we can use the additivity of the probability, and obtain
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &\leq p \ProbCond{\bigcup_{(k, i) \in \N \times [n]} \left(\{(k^{\xi}_{j,l_{j+1}}, i^{\xi}_{j,l_{j+1}}) = (k, i)\} \bigcap A_{(k, i)}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq p.
    \end{align*}
    Otherwise, if $l_{j+1} > 1,$ we also use the fact that the events do not intersect and get
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &\leq p \sum_{S_{l_{j+1} - 1}} \ProbCond{\bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k_p}_{i_p}=0\}, \bigcap_{p=1}^{l_{j+1} - 1} \left(\{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap A_{(k_p, i_p)}\right), \right.\\
        &\qquad\qquad\qquad\qquad\left.\bigcup_{(k, i) > (k_{l_{j+1} - 1}, i_{l_{j+1} - 1})} \left(\{(k^{\xi}_{j,l_{j+1}}, i^{\xi}_{j,l_{j+1}}) = (k, i)\} \bigcap A_{(k, i)}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \\
        &\leq p \sum_{S_{l_{j+1} - 1}} \ProbCond{\bigcap_{p=1}^{l_{j+1} - 1} \{\xi^{k_p}_{i_p}=0\}, \bigcap_{p=1}^{l_{j+1} - 1} \left(\{(k^{\xi}_{j,p}, i^{\xi}_{j,p}) = (k_p, i_p)\} \bigcap A_{(k_p, i_p)}\right)}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}},
    \end{align*}
    where we used an inequality $\Prob{A, B} \leq \Prob{A}$ for any events $A$ and $B.$ 
    We take the sum over all $((k_1, i_1), \dots, (k_{l_{j+1} - 1}, i_{l_{j+1} - 1})) \in S_{l_{j+1} - 1},$ where $$S_{l_{j+1} - 1} = \{((k_1, i_1), \dots, (k_{l_{j+1} - 1}, i_{l_{j+1} - 1})) \in (\N \times [n])^{l_{j+1} - 1} \,|\, \forall p < j \in [l_{j+1} - 1] : (k_p, i_p) < (k_j, i_j)\}.$$
    Using the same reasoning, one can continue and get that
    \begin{align*}
        &\ProbCond{\eta_{j+1} = l_{j+1}}{\bigcap_{i=1}^{j}\{\eta_{i} = l_{i}\}} \leq p (1 - p)^{l_{j+1} - 1}.
    \end{align*}
\end{proof}

