\section{Proofs for Convex Case}

\subsection{The ``worst case'' function in convex case}
\label{sec:worst_case_convex}

In this proof, we use the construction from \citep{woodworth2018graph}. Let us define $B_2(0, R) \eqdef \left\{x \in \R^{T+1}\,:\, \norm{x} \leq R\right\}.$

Let us take functions $f_{l, \eta}\,:\,\R^{T+1} \rightarrow \R$ and $\widetilde{f}_{l, \eta}\,:\,\R^{T+1} \rightarrow \R$ such that 
\begin{align*}
    f_{l, \eta}(x) \eqdef \min_{y \in \R^{T+1}} \left\{\widetilde{f}_{l, \eta}(y) + \frac{\eta}{2} \norm{y - x}^2\right\}
\end{align*}
and 
\begin{align*}
    \widetilde{f}_{l, \eta}(x) \eqdef \max_{1 \leq r \leq T + 1} \left(l x_r - \frac{5 l^2 (r - 1)}{\eta} \right),
\end{align*}
where $l, \eta > 0$ are free parameters. Let us define
\begin{align*}
    y(x) \eqdef \argmin_{y \in \R^{T+1}} \left\{\widetilde{f}_{l, \eta}(y) + \frac{\eta}{2} \norm{y - x}^2\right\}.
\end{align*}


For ths function $f_{l, \eta},$ we have the following properties:
\begin{lemma}[\cite{woodworth2018graph}]
    \label{lemma:worst_function_convex} 
    The function $f_{l, \eta}$ satisfies:
    \begin{enumerate}
    \item
    (Lemma 4) The function $f_{l, \eta}$ is convex, $l$--Lipschitz, and $\eta$--smooth.
    \item (eq. 75)
    \begin{align*}
        \min_{x \in B_2(0, 1)} f_{l, \eta}(x) \leq -\frac{l}{\sqrt{T + 1}}.
    \end{align*}
    \item (Lemma 6) For all $x \in B_2(0, 1),$ $\textnormal{prog}(\nabla f_{l, \eta}(x)) \leq \textnormal{prog}(x) + 1$ and $\textnormal{prog}(y(x)) \leq \textnormal{prog}(x) + 1.$
    \end{enumerate}
\end{lemma}


\subsection{Proof of Theorem~\ref{theorem:lower_bound_homog_convex}}

\THEOREMLOWERBOUNDCONVEX*

In Step 1, we almost repeat the proof from \cite{woodworth2018graph}. Steps 2 and 3 are very close to Steps 2 and 3 of the proofs for the nonconvex case.

\begin{proof}
    (\textbf{Step 1}: $f \in \cF^{\textnormal{conv}}_{R, M, L}$)
    Following \cite{woodworth2018graph}, we assume that $R = 1.$ Otherwise, one can rescale the parameters of the construction. Let us take the function $f_{l, \eta}$ from Section~\ref{sec:worst_case_convex} with parameters
    \begin{align*}
        l = \min\left\{M, \frac{L}{10 (T + 1)^{3/2}}\right\} \textnormal{ and } \eta = 10 (T + 1)^{3/2} l.
    \end{align*}
    Using Lemma~\ref{lemma:worst_function_convex}, one can see that $f_{l, \eta}$ is convex, $M$--Lipschitz, and $L$--smooth. Therefore, $f_{l, \eta} \in \cF^{\textnormal{conv}}_{R, M, L}.$ Further, we use the notation $f \eqdef f_{l, \eta}.$

    (\textbf{Step 2}: Oracle Class) \\
    Let us take 
    \begin{align*}[\widehat{\nabla} f(x; \xi)]_j \eqdef \nabla_j f(x) \left(1 + \mathbbm{1}\left[j > \textnormal{prog}(x)\right]\left(\frac{\xi}{p} - 1\right)\right) \quad \forall x \in \R^T,
    \end{align*} and $\mathcal{D}_i = \textnormal{Bernouilli}(p)$ for all $i \in [n],$ where $p \in (0, 1].$ We denote $[x]_j$ as the $j$\textsuperscript{th} index of a vector $x \in \R^{T+1}.$
    It is left to show this mapping is unbiased and $\sigma^2$-variance-bounded. Indeed, $$\Exp{[\widehat{\nabla} f(x, \xi)]_i} = \nabla_i f(x) \left(1 + \mathbbm{1}\left[i > \textnormal{prog}(x)\right]\left(\frac{\Exp{\xi}}{p} - 1\right)\right) = \nabla_i f(x)$$ for all $i \in [T+1],$ and
    \begin{align*}
        \Exp{\norm{\widehat{\nabla} f(x; \xi) - \nabla f(x)}^2} \leq \max_{j \in [T+1]} \left|\nabla_j f(x)\right|^2\Exp{\left(\frac{\xi}{p} - 1\right)^2}
    \end{align*}
    because the difference is non-zero only in one coordinate. Thus
    \begin{align*}
        \Exp{\norm{\widehat{\nabla} f(x, \xi) - \nabla f(x)}^2} &\leq \frac{\norm{\nabla f(x)}_{\infty}^2(1 - p)}{p} \leq \frac{\norm{\nabla f(x)}^2(1 - p)}{p} \\
        &\leq \frac{l^2 (1 - p)}{p} \leq \sigma^2 \quad \forall x \in B_2(0, 1).
    \end{align*}
    where we take 
    $$p = \min\left\{\frac{l^2}{\sigma^2}, 1\right\}.$$

    (\textbf{Step 3}: Analysis of Protocol) \\
    Protocol~\ref{alg:time_multiple_oracle_protocol} generates the sequence $\{x^k\}_{k=0}^{\infty}.$
    Then, we have
    \begin{align*}
        f(x^k) &= \max_{1 \leq r \leq T + 1} \left(l [y(x^k)]_r  - \frac{5 l^2 (r - 1)}{\eta} \right) + \frac{\eta}{2} \norm{y(x^k) - x^k}^2 \geq l [y(x^k)]_{T+1}  - \frac{5 l^2 T}{\eta}.
    \end{align*}
    Assume that $\textnormal{prog}(x^k) < T.$ Using Lemma~\ref{lemma:worst_function_convex}, if $\textnormal{prog}(x^k) < T,$ then $\textnormal{prog}(y(x^k)) \leq T$ and $[y(x^k)]_{T+1} = 0.$ Therefore, $f(x^k) \geq - \frac{5 l^2 T}{\eta} \geq - \frac{5 l^2 (T + 1)}{\eta}$ and
    \begin{align*}
        f(x^k) - \min_{x \in B_2(0, 1)} f(x) \geq \frac{l}{\sqrt{T + 1}} - \frac{5 l^2 (T+1)}{\eta} = \frac{l}{2 \sqrt{T + 1}} = \min\left\{\frac{M}{2 \sqrt{T + 1}}, \frac{L}{20 (T + 1)^2}\right\}
    \end{align*}
    if $\textnormal{prog}(x^k) < T.$ Let us take
    \begin{align*}
        T = \min\left\{\left\lfloor\frac{M^2}{64 \varepsilon^2} - 1\right\rfloor, \left\lfloor\frac{\sqrt{L}}{\sqrt{80} \sqrt{\varepsilon}} - 1\right\rfloor\right\}
    \end{align*}
    to ensure that
    \begin{align*}
        f(x^k) - \min_{x \in B_2(0, 1)} f(x) \geq \min\left\{\frac{M}{2 \sqrt{T + 1}}, \frac{L}{20 (T + 1)^2}\right\} \geq 4 \varepsilon > 2 \varepsilon
    \end{align*}
    if $\textnormal{prog}(x^k) < T.$
    It is left to use Lemma~\ref{lemma:boundtime} with $\delta = 1/2$:
    \begin{align}
        \label{eq:aux_convex_varepsilon}
        \Exp{\inf_{k \in S_t} f(x^k)} - \min_{x \in B_2(0, 1)} f(x) &> 2 \varepsilon \Prob{\inf_{k \in S_t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] \geq 1} > \varepsilon
    \end{align}
    for \begin{align*}
        t &\leq \frac{1}{24} \min_{m \in [n]} \left[\left(\sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{\sigma^2}{l^2} + m\right)\right] \left(\frac{T}{2} - 1\right) \\
        &= \frac{1}{24} \min_{m \in [n]} \left[\left(\frac{1}{m} \sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{\sigma^2}{m l^2} + 1\right)\right] \left(\frac{T}{2} - 1\right).
    \end{align*}
    We can take universal constants $c_1$ and $c_2$ equal to $8 \cdot 64$ to ensure that $T \geq 6.$ Therefore, $16\varepsilon \geq \frac{l}{2 \sqrt{T + 1}}$ and \eqref{eq:aux_convex_varepsilon} holds for 
    \begin{align*}
        t &\leq \frac{1}{96} \min_{m \in [n]} \left[\left(\frac{1}{m} \sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{\sigma^2}{m l^2} (T + 1) + (T + 2)\right)\right],
    \end{align*}
    for
    \begin{align*}
        t &\leq \frac{1}{96} \min_{m \in [n]} \left[\left(\frac{1}{m} \sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{\sigma^2}{m l^2} \frac{l^2}{32^2 \varepsilon^2} + (T + 2)\right)\right],
    \end{align*}
    and for
    \begin{align*}
        t &\leq \frac{1}{96} \min_{m \in [n]} \left[\left(\frac{1}{m} \sum_{i=1}^{m} \frac{1}{\tau_i}\right)^{-1} \left(\frac{\sigma^2}{32^2 m \varepsilon^2} + \min\left\{\frac{M^2}{64 \varepsilon^2}, \frac{\sqrt{L}}{\sqrt{80} \sqrt{\varepsilon}}\right\}\right)\right].
    \end{align*}
\end{proof}

\subsection{Proof of Theorem~\ref{thm:sgd_homog_convex}}

\THEOREMSGDHOMOGCONVEX*

\begin{proof}
    Using the same reasoning as in the proof of Theorem~\ref{thm:sgd_homog}, one can see that Method~\ref{alg:alg_server} is just the stochastic gradient method with the batch size $S.$ Method~\ref{alg:alg_server} can be rewritten as $x^{k+1} = x^k - \gamma \frac{1}{S} \sum_{i=1}^S \widehat{\nabla} f(x^k;\xi_i),$ where the $\xi_i$ are independent random samples. It means that we can use the classical SGD result (Theorem~\ref{theorem:sgd_convex}). For a stepsize $$\gamma = \frac{\varepsilon}{M^2 + \frac{\sigma^2}{S}},$$ we have
    \begin{align*}
        \Exp{f(\widehat{x}^K)} - f(x^*) \leq \varepsilon
    \end{align*}
    if $$K \geq \frac{2 M^2 \norm{x^* - x^{0}}^2}{\varepsilon^2} \geq \frac{(M^2 + \frac{\sigma^2}{S})\norm{x^* - x^{0}}^2}{\varepsilon^2}.$$
\end{proof}

\subsubsection{The classical SGD theorem in convex optimization}
We reprove the classical SGD result (see, for instance, \citep{lan2020first}) for convex functions.
\begin{theorem}
    \label{theorem:sgd_convex}
    Assume that Assumptions~\ref{ass:convex} and \ref{ass:lipschitz_constant_function} hold. We consider the SGD method: $$x^{k+1} = x^k - \gamma g(x^k),$$ where
    \begin{align*}
        \gamma = \frac{\varepsilon}{M^2 + \sigma^2}
    \end{align*} 
    For a fixed $x \in \R^d$, $g(x)$ is a random vector such that $\Exp{g(x)} \in \partial f(x)$ ($\partial f(x)$ is the subdifferential of the function $f$ at the point $x$), \begin{align*}
        \Exp{\norm{g(x) - \Exp{g(x)}}^2} \leq \sigma^2,
    \end{align*} and $g(x^k)$ are independent vectors for all $k \geq 0.$ Then
    \begin{align}
        \label{eq:stoch_mirr_desc}
        \Exp{f\left(\frac{1}{K} \sum_{k=0}^{K-1} x^k\right)} - f(x^*) \leq \varepsilon
    \end{align}
    for
    \begin{align*}
        K \geq \frac{(M^2 + \sigma^2)\norm{x^* - x^{0}}^2}{\varepsilon^2}.
    \end{align*}
\end{theorem}

\begin{proof}
    We denote $\mathcal{G}^k$ as a sigma-algebra generated by $g(x^0), \dots, g(x^{k-1}).$ Using the convexity, for all $x \in \R^d,$ we have
    \begin{align*}
        f(x) \geq f(x^k) + \inp{\ExpCond{g(x^k)}{\mathcal{G}^k}}{x - x^k} = f(x^k) + \ExpCond{\inp{g(x^k)}{x - x^k}}{\mathcal{G}^k}.
    \end{align*}
    Note that
    \begin{align*}
        \inp{g(x^k)}{x - x^k} &= \inp{g(x^k)}{x^{k+1} - x^k} + \inp{g(x^k)}{x - x^{k+1}} \\
        &= -\gamma \norm{g(x^k)}^2 + \frac{1}{\gamma}\inp{x^k - x^{k+1}}{x - x^{k+1}} \\
        &= -\gamma \norm{g(x^k)}^2 + \frac{1}{2\gamma}\norm{x^k - x^{k+1}}^2 + \frac{1}{2\gamma}\norm{x - x^{k+1}}^2 - \frac{1}{2\gamma}\norm{x - x^{k}}^2 \\
        &= -\frac{\gamma}{2} \norm{g(x^k)}^2 + \frac{1}{2\gamma}\norm{x - x^{k+1}}^2 - \frac{1}{2\gamma}\norm{x - x^{k}}^2
    \end{align*}
    and
    \begin{align*}
        \ExpCond{\norm{g(x^k)}^2}{\mathcal{G}^k} = \ExpCond{\norm{g(x^k) - \ExpCond{g(x^k)}{\mathcal{G}^k}}^2}{\mathcal{G}^k} + \norm{\ExpCond{g(x^k)}{\mathcal{G}^k}}^2 \leq \sigma^2 + M^2.
    \end{align*}
    Therefore, we get
    \begin{align*}
        f(x^k) &\leq f(x) + \ExpCond{\inp{g(x^k)}{x^k - x}}{\mathcal{G}^k} \\
        &= f(x) + \frac{\gamma}{2} \ExpCond{\norm{g(x^k)}^2}{\mathcal{G}^k} + \frac{1}{2\gamma}\norm{x - x^{k}}^2 - \frac{1}{2\gamma}\ExpCond{\norm{x - x^{k+1}}^2}{\mathcal{G}^k} \\
        &\leq f(x) + \frac{\gamma}{2} \left(M^2 + \sigma^2\right) + \frac{1}{2\gamma}\norm{x - x^{k}}^2 - \frac{1}{2\gamma}\ExpCond{\norm{x - x^{k+1}}^2}{\mathcal{G}^k}.
    \end{align*}
    By taking the full expectation and summing the last inequality for $t$ from $0$ to $K - 1,$ we obtain
    \begin{align*}
        \Exp{\sum_{k=0}^{K-1} f(x^k)} &\leq K f(x) + \frac{K \gamma}{2} \left(M^2 + \sigma^2\right) + \frac{1}{2\gamma}\norm{x - x^{0}}^2 - \frac{1}{2\gamma}\Exp{\norm{x - x^{K}}^2} \\
        &\leq K f(x) + \frac{K \gamma}{2} \left(M^2 + \sigma^2\right) + \frac{1}{2\gamma}\norm{x - x^{0}}^2.
    \end{align*}
    Let divide the last inequality by $K,$ take $x = x^*,$ and use the convexity:
    \begin{align*}
        \Exp{f\left(\frac{1}{K} \sum_{k=0}^{K-1} x^k\right)} - f(x^*) \leq \frac{\gamma}{2} \left(M^2 + \sigma^2\right) + \frac{1}{2\gamma K}\norm{x^* - x^{0}}^2.
    \end{align*}
    The choices of $\gamma$ and $K$ ensure that \eqref{eq:stoch_mirr_desc} holds.
\end{proof}

